/* مولّد تلقائياً من panel/panel.html — لا تعدّله يدوياً (شغّل: python3 scripts/build_panel.py) */
export const PANEL_HTML = "<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>لوحة دليل السعودية</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css\">\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js\"></script>\n<style>\n.geo{position:relative}\n.geo .map{height:280px;border-radius:16px;margin-top:8px;border:1.5px solid var(--line);z-index:1}\n.sug{position:absolute;top:46px;right:0;left:0;background:#fff;border-radius:14px;box-shadow:0 10px 30px rgba(43,39,69,.18);z-index:5;overflow:hidden;display:none}\n.sug div{padding:10px 14px;cursor:pointer;border-bottom:1px solid var(--chip)}\n.sug div:hover{background:var(--chip)}\n.sug b{display:block;font-size:14px}.sug span{font-size:12px;color:var(--muted)}\n:root{--ink:#2B2745;--muted:#6B6585;--faint:#9C94B5;--purple:#604C87;--lilac:#8E65AB;--orange:#F89743;--orangeDeep:#E07B22;--pink:#EB839B;--pinkDeep:#C9506F;--sky:#62B9E8;--skyDeep:#2E86B8;--green:#3E8E5A;--bg:#F4F1EE;--line:#E2DAEC;--chip:#F1ECF6;--white:#fff;--softPurple:#ECE5F3;--softOrange:#FDE7D3;--softPink:#FBE3EA;--softGreen:#E2F0E6;--softSky:#E2F1FA}\n*{box-sizing:border-box}\nbody{margin:0;font-family:'IBM Plex Sans Arabic',system-ui,sans-serif;background:var(--bg);color:var(--ink);font-size:15px}\nbutton,input,select,textarea{font:inherit;color:inherit}\na{color:var(--purple)}\n.app{display:flex;min-height:100vh}\naside{width:230px;background:var(--ink);color:#fff;padding:18px 14px;position:sticky;top:0;height:100vh;flex-shrink:0;display:flex;flex-direction:column;gap:2px;overflow-y:auto}\n.brand{display:flex;align-items:center;gap:10px;padding:0 8px 18px;font-weight:700;font-size:17px}\n.brand i{width:36px;height:36px;border-radius:11px;background:var(--orange);display:grid;place-items:center;font-style:normal}\n.nav{display:flex;align-items:center;gap:10px;padding:8px 12px;flex-shrink:0;border-radius:12px;cursor:pointer;color:#CFC6DE;font-weight:600;border:0;background:none;text-align:right;width:100%}\n.nav:hover{background:rgba(255,255,255,.07)}\n.nav.on{background:var(--orange);color:#fff}\n.nav b{margin-inline-start:auto;background:var(--pinkDeep);color:#fff;border-radius:999px;padding:0 8px;font-size:12px}\naside .foot{margin-top:auto;font-size:12px;color:#9C94B5;padding:8px}\nmain{flex:1;min-width:0;padding:26px 28px 80px}\nh1{font-size:26px;margin:0 0 4px}\n.sub{color:var(--muted);margin:0 0 20px}\n.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n.grow{flex:1}\n.stats{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:20px}\n.stat{background:#fff;border-radius:20px;padding:16px}\n.stat .n{font-size:28px;font-weight:700}\n.stat .l{color:var(--muted);font-size:13px}\n.card{background:#fff;border-radius:20px;padding:16px}\n.btn{border:0;border-radius:12px;padding:9px 16px;font-weight:700;cursor:pointer;background:var(--purple);color:#fff;white-space:nowrap}\n.btn.o{background:var(--orange)}.btn.g{background:var(--green)}.btn.p{background:var(--pinkDeep)}\n.btn.ghost{background:var(--chip);color:var(--ink)}\n.btn:disabled{opacity:.5;cursor:default}\n.in,select.in,textarea.in{background:#fff;border:1.5px solid var(--line);border-radius:12px;padding:9px 12px;width:100%;outline:none}\n.in:focus{border-color:var(--lilac)}\ntextarea.in{min-height:130px;resize:vertical;line-height:1.8}\n.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}\n.filters .in{width:auto;min-width:150px}\n.list{display:grid;gap:10px}\n.item{display:flex;gap:12px;align-items:center;background:#fff;border-radius:18px;padding:10px;cursor:pointer;border:2px solid transparent}\n.item:hover{border-color:var(--line)}\n.item img,.item .ph{width:64px;height:64px;border-radius:14px;object-fit:cover;background:var(--chip);flex-shrink:0;display:grid;place-items:center;color:var(--faint);font-size:12px}\n.item .t{font-weight:700}\n.item .m{color:var(--muted);font-size:13px}\n.badge{display:inline-block;border-radius:999px;padding:2px 10px;font-size:12px;font-weight:700}\n.b-live{background:var(--softGreen);color:var(--green)}.b-draft{background:var(--softOrange);color:var(--orangeDeep)}.b-hidden{background:var(--chip);color:var(--muted)}\n.b-panel{background:var(--softPurple);color:var(--purple)}\n.tabs{display:flex;gap:6px;background:#fff;border-radius:14px;padding:4px;width:fit-content;margin-bottom:14px}\n.tabs button{border:0;background:none;padding:7px 14px;border-radius:10px;font-weight:700;cursor:pointer;color:var(--muted)}\n.tabs button.on{background:var(--purple);color:#fff}\n.drawer{position:fixed;inset:0;background:rgba(43,39,69,.45);display:none;z-index:20}\n.drawer.on{display:block}\n.sheet{position:absolute;top:0;bottom:0;left:0;width:min(720px,100%);background:var(--bg);overflow:auto;padding:22px 24px 120px;box-shadow:0 0 40px rgba(0,0,0,.2)}\n.sheet h2{margin:0;font-size:22px}\n.f{display:grid;gap:6px;margin-top:14px}\n.f label{font-weight:700;font-size:13px}\n.f small{color:var(--muted);font-size:12px}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.chips{display:flex;gap:6px;flex-wrap:wrap}\n.chip{border:1.5px solid var(--line);background:#fff;border-radius:999px;padding:4px 12px;cursor:pointer;font-size:13px;font-weight:600}\n.chip.on{background:var(--purple);border-color:var(--purple);color:#fff}\n.imgs{display:flex;gap:8px;flex-wrap:wrap}\n.imgs .im{position:relative;width:110px;height:84px;border-radius:12px;overflow:hidden;background:var(--chip)}\n.imgs .im img{width:100%;height:100%;object-fit:cover}\n.imgs .im .x{position:absolute;top:4px;left:4px;width:24px;height:24px;border-radius:12px;background:rgba(0,0,0,.6);color:#fff;border:0;cursor:pointer}\n.imgs .im .cover{position:absolute;bottom:4px;right:4px;background:var(--orange);color:#fff;font-size:11px;border-radius:999px;padding:0 8px;font-weight:700}\n.imgs .im .mk{position:absolute;bottom:4px;right:4px;background:rgba(255,255,255,.85);border:0;border-radius:999px;font-size:11px;padding:0 8px;cursor:pointer}\n.up{font:inherit;line-height:1.5;width:110px;height:84px;border-radius:12px;border:2px dashed var(--line);display:grid;place-items:center;cursor:pointer;color:var(--muted);font-size:13px;background:#fff}\n.bar{position:sticky;bottom:-120px;margin:22px -24px -120px;padding:14px 24px 24px;background:linear-gradient(transparent,var(--bg) 30%);display:flex;gap:8px;flex-wrap:wrap}\n.im[draggable=true]{cursor:grab}.im.dragging{opacity:.4}.im.over{outline:3px solid var(--orange)}\n.warn{background:var(--softOrange);color:var(--orangeInk,#995306);border-radius:14px;padding:10px 14px;font-size:13px;margin-top:10px}\n.warn a{color:inherit;font-weight:700}\n.prev{background:#fff;border-radius:22px;overflow:hidden;max-width:340px;box-shadow:0 8px 30px rgba(43,39,69,.12);margin-top:10px}\n.prev .cv{height:170px;background:var(--chip) center/cover;position:relative}\n.prev .cv b{position:absolute;bottom:10px;right:10px;background:#fff;border-radius:999px;padding:2px 10px;font-size:12px}\n.prev .bd{padding:14px}.prev h3{margin:0;font-size:19px}.prev p{margin:6px 0 0;color:var(--muted);font-size:13px;line-height:1.8}\n.mini{border:0;border-radius:10px;padding:5px 12px;font-weight:700;cursor:pointer;font-size:13px}\n.season{background:#fff;border-radius:20px;padding:16px;cursor:pointer;border-right:6px solid var(--purple)}\n.toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);background:var(--ink);color:#fff;padding:10px 18px;border-radius:14px;font-weight:600;z-index:50;display:none}\n.empty{color:var(--muted);text-align:center;padding:40px}\n.login{max-width:380px;margin:12vh auto;background:#fff;border-radius:26px;padding:28px;text-align:center}\n.login i{display:inline-grid;place-items:center;width:64px;height:64px;border-radius:20px;background:var(--purple);color:#fff;font-style:normal;font-size:28px;margin-bottom:10px}\n.post{background:#fff;border-radius:18px;padding:14px;display:grid;gap:8px}\n.muted{color:var(--muted)}\n.tag{font-size:12px;color:var(--skyDeep);font-weight:700}\n.hint{background:var(--softPurple);border-radius:14px;padding:10px 14px;font-size:13px;color:var(--purple)}\n/* لوحة القيادة */\n.kpis{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin-bottom:14px}\n.kpi{background:#fff;border-radius:18px;padding:14px 16px;cursor:default}.kpi[data-go]{cursor:pointer}.kpi .l{color:var(--muted);font-size:12.5px;font-weight:600}\n.kpi .n{font-size:28px;font-weight:700;line-height:1.3}.kpi .s{font-size:11.5px;color:var(--faint)}\n.dup{color:var(--green);font-weight:700}.ddown{color:var(--pinkDeep);font-weight:700}\n.dgrid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:14px;margin-bottom:14px}\n.dgrid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:14px}\n.task{display:flex;gap:10px;align-items:center;padding:9px 6px;border-bottom:1px solid var(--chip);cursor:pointer;border-radius:8px}.task:hover{background:var(--chip)}.task b{min-width:30px;font-size:17px}\n.li{display:flex;gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid var(--chip);font-size:14px}.li[data-place],.li[data-ev]{cursor:pointer}\n.rk{width:22px;height:22px;border-radius:7px;background:var(--chip);display:grid;place-items:center;font-size:12px;font-weight:700;color:var(--purple)}\n.lg{font-size:12px;color:var(--muted);display:inline-flex;align-items:center;gap:5px}.lg i{width:10px;height:10px;border-radius:3px;display:inline-block}\n.ok{background:var(--softGreen);color:var(--green);border-radius:12px;padding:12px;font-weight:700;text-align:center}\n.mini-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px}.mini-stats div{background:var(--bg);border-radius:12px;padding:8px;text-align:center}.mini-stats b{display:block;font-size:18px}.mini-stats span{font-size:11.5px;color:var(--muted)}\n@media (max-width:1200px){.kpis{grid-template-columns:repeat(3,minmax(0,1fr))}.dgrid3{grid-template-columns:1fr 1fr}}\n@media (max-width:820px){\n  .kpis{grid-template-columns:1fr 1fr}.dgrid,.dgrid3{grid-template-columns:1fr}\n  .msgGrid{grid-template-columns:1fr!important}\n  .app{flex-direction:column}\n  aside{width:auto;height:auto;position:sticky;top:0;z-index:10;flex-direction:row;overflow-x:auto;padding:10px;gap:4px}\n  .brand,aside .foot{display:none}\n  .nav{width:auto;white-space:nowrap;padding:8px 12px}\n  main{padding:18px 16px 80px}\n  .two{grid-template-columns:1fr}\n  .sheet{padding:18px 16px 120px}\n  .bar{margin:22px -16px -120px;padding:14px 16px 24px}\n}\n</style>\n</head>\n<body>\n<div id=\"root\"></div>\n<div class=\"toast\" id=\"toast\"></div>\n<script>\nconst API = location.origin;\nconst KIND = { islamic: 'معالم إسلامية', heritage: 'تراث وثقافة', nature: 'طبيعة', sights: 'معالم سياحية', fun: 'ترفيه', food: 'مطاعم', cafe: 'مقاهي', shopping: 'تسوق' };\nconst ST = { live: ['منشور', 'b-live'], draft: ['مسودة', 'b-draft'], hidden: ['مخفي', 'b-hidden'] };\nconst EV_TYPES = ['حفلات غنائية', 'مسرح', 'رياضية', 'مهرجانات', 'معارض ومؤتمرات', 'تراث وثقافة', 'ترفيه', 'تجارب ومغامرات', 'عائلية', 'طعام'];\nconst SEASONS = ['موسم الرياض', 'موسم جدة', 'موسم الدرعية', 'لحظات العلا'];\nlet KEY = localStorage.getItem('sg_admin') || '';\nlet META = null, VIEW = 'home', SUMMARY = null;\nconst $ = (s, el = document) => el.querySelector(s);\nconst h = (s) => String(s ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nconst cityName = (id) => META?.cities.find((c) => c.id === id)?.name || id || '—';\nfunction toast(t) { const el = $('#toast'); el.textContent = t; el.style.display = 'block'; clearTimeout(toast.t); toast.t = setTimeout(() => (el.style.display = 'none'), 2600); }\n\nasync function api(path, opt = {}) {\n  const r = await fetch(API + path, { method: opt.method || 'GET', headers: { 'X-Admin-Key': KEY, ...(opt.body && !(opt.body instanceof Blob) ? { 'Content-Type': 'application/json' } : {}), ...(opt.headers || {}) }, body: opt.body instanceof Blob ? opt.body : opt.body ? JSON.stringify(opt.body) : undefined });\n  const d = await r.json().catch(() => ({}));\n  if (r.status === 401) { const wasIn = !!localStorage.getItem('sg_admin'); KEY = ''; localStorage.removeItem('sg_admin'); if (wasIn) render(); throw new Error('unauthorized'); }\n  if (!r.ok) throw new Error(d.error || 'http_' + r.status);\n  return d;\n}\nconst ERR = { text_required: 'اكتب الرسالة', title_required: 'اكتب الاسم', start_required: 'حدد تاريخ البداية', bad_city: 'اختر المدينة', bad_type: 'الصورة لازم JPG أو PNG أو WEBP', bad_size: 'الصورة أكبر من 10MB', bad_time: 'الوقت لازم يكون بعد الحين', no_channel: 'اختر قناة وحدة على الأقل' };\nconst errMsg = (e) => ERR[e.message] || 'صار خطأ: ' + e.message;\n\n/* ——— الدخول ——— */\nfunction loginView() {\n  $('#root').innerHTML = `<div class=\"login\"><i>د</i><h1 style=\"font-size:22px\">لوحة دليل السعودية</h1>\n    <p class=\"sub\">اضغط الزر البرتقالي عشان يلصق مفتاح الإدارة اللي نسخه لك أمر «افتح-اللوحة».</p>\n    <button class=\"btn o\" style=\"width:100%;padding:14px;font-size:17px\" id=\"paste\">الصق المفتاح وادخل</button>\n    <p class=\"muted\" style=\"margin:16px 0 8px;font-size:13px\">أو الصقه يدوياً هنا (Cmd+V):</p>\n    <input class=\"in\" id=\"k\" type=\"password\" placeholder=\"مفتاح الإدارة\" autocomplete=\"off\" autofocus>\n    <button class=\"btn\" style=\"width:100%;margin-top:10px\" id=\"go\">دخول</button><p id=\"msg\" style=\"color:var(--pinkDeep);font-weight:700\"></p></div>`;\n  const go = async (k) => {\n    const raw = String(k || $('#k').value);\n    // المفتاح حروف وأرقام إنجليزية بس — نطلعه حتى لو انلصق معه كلام ثاني\n    KEY = (raw.match(/[A-Za-z0-9_-]{8,}/) || [''])[0];\n    if (!raw.trim()) { $('#msg').textContent = 'ما فيه شي منسوخ. شغّل أمر «افتح-اللوحة» مرة ثانية، وبعده لا تنسخ أي شي ثاني'; return; }\n    if (!KEY) { $('#msg').textContent = 'اللي منسوخ مو المفتاح (غالباً نسخت شي بعد الأمر). شغّل أمر «افتح-اللوحة» مرة ثانية، وبعده اضغط الزر البرتقالي على طول'; return; }\n    try { await api('/admin/summary'); localStorage.setItem('sg_admin', KEY); render(); }\n    catch (e) { KEY = ''; $('#msg').textContent = e.message === 'unauthorized' ? 'المفتاح غلط. شغّل أمر «افتح-اللوحة» مرة ثانية' : 'السيرفر ما رد: ' + e.message; }\n  };\n  $('#paste').onclick = async () => {\n    try { const t = await navigator.clipboard.readText(); go(t); }\n    catch { $('#msg').textContent = 'المتصفح ما سمح باللصق. اضغط داخل الخانة تحت واضغط Cmd+V'; $('#k').focus(); }\n  };\n  $('#go').onclick = () => go(); $('#k').onkeydown = (e) => { if (e.key === 'Enter') go(); };\n  setTimeout(() => $('#k').focus(), 100);\n}\n\n/* ——— الهيكل ——— */\nconst NAV = [['home', 'الرئيسية'], ['places', 'الأماكن'], ['events', 'الفعاليات'], ['seasons', 'المواسم'], ['weekly', 'مختارات الأسبوع'], ['articles', 'الأخبار'], ['community', 'المجتمع'], ['merchants', 'التجار والكوبونات'], ['photos', 'صور وتقييمات'], ['messages', 'الرسائل'], ['suggest', 'اقتراحات الزوار'], ['badges', 'الأوسمة والنقاط'], ['analytics', 'التحليلات'], ['users', 'المستخدمين'], ['features', 'المميزات']];\nasync function render() {\n  if (!KEY) return loginView();\n  if (!META) { try { META = await api('/admin/meta'); } catch (e) { if (KEY) $('#root').innerHTML = `<div class=\"login\"><p>ما قدرنا نحمّل اللوحة (${h(e.message)}). حدّث الصفحة.</p></div>`; return; } }\n  const rep = SUMMARY?.counts?.reported || 0;\n  const NB = { community: rep + (SUMMARY?.counts?.communityPending || 0), merchants: (SUMMARY?.counts?.merchantsPending || 0) + (SUMMARY?.counts?.couponsPending || 0) + (SUMMARY?.counts?.creportsPending || 0), photos: (SUMMARY?.counts?.photosPending || 0) + (SUMMARY?.counts?.reviewsReported || 0), users: SUMMARY?.counts?.guidesPending || 0, suggest: SUMMARY?.counts?.suggPending || 0 };\n  $('#root').innerHTML = `<div class=\"app\"><aside><div class=\"brand\"><i>د</i>لوحة الدليل</div>\n    ${NAV.map(([id, t]) => `<button class=\"nav ${VIEW === id ? 'on' : ''}\" data-v=\"${id}\">${t}${NB[id] ? `<b>${NB[id]}</b>` : ''}</button>`).join('')}\n    <div class=\"foot\">كل وقت بتوقيت مكة<br><a href=\"#\" id=\"out\" style=\"color:#CFC6DE\">خروج</a></div></aside><main id=\"main\"></main></div>`;\n  document.querySelectorAll('.nav').forEach((b) => (b.onclick = () => { VIEW = b.dataset.v; render(); }));\n  $('#out').onclick = (e) => { e.preventDefault(); KEY = ''; localStorage.removeItem('sg_admin'); render(); };\n  ({ home: homeView, places: placesView, events: eventsView, seasons: seasonsView, weekly: weeklyView, articles: articlesView, community: communityView, merchants: merchantsView, photos: photosView, messages: messagesView, badges: badgesView, analytics: analyticsView, users: usersView, suggest: suggestView, features: featuresView })[VIEW]();\n  if (!SUMMARY && VIEW !== 'home') api('/admin/summary').then((x) => { SUMMARY = x; }).catch(() => {});\n}\n\n/* ——— الرئيسية: لوحة القيادة ——— */\nfunction chart2(a, b, W = 600, H = 150) {\n  const mx = Math.max(1, ...a, ...b), step = W / (a.length - 1 || 1);\n  const pts = (arr) => arr.map((v, i) => `${(i * step).toFixed(1)},${(H - 6 - (v / mx) * (H - 20)).toFixed(1)}`).join(' ');\n  const grid = [0.25, 0.5, 0.75].map((f) => `<line x1=\"0\" x2=\"${W}\" y1=\"${(H - 6 - f * (H - 20)).toFixed(1)}\" y2=\"${(H - 6 - f * (H - 20)).toFixed(1)}\" stroke=\"#EEE9F2\" stroke-width=\"1\"/>`).join('');\n  return `<svg viewBox=\"0 0 ${W} ${H}\" style=\"width:100%;height:${H}px;display:block;direction:ltr\" preserveAspectRatio=\"none\">${grid}\n    <polyline points=\"0,${H} ${pts(a)} ${W},${H}\" fill=\"#604C8718\" stroke=\"none\"/><polyline points=\"${pts(a)}\" fill=\"none\" stroke=\"#604C87\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/>\n    <polyline points=\"${pts(b)}\" fill=\"none\" stroke=\"#F89743\" stroke-width=\"2\" stroke-dasharray=\"5 4\" stroke-linejoin=\"round\"/></svg>`;\n}\nasync function homeView() {\n  const m = $('#main');\n  m.innerHTML = '<p class=\"muted\">لحظة...</p>';\n  const [d, sum] = await Promise.all([api('/admin/dashboard'), api('/admin/summary')]);\n  SUMMARY = sum;\n  const k = d.kpi, a = d.active;\n  const mk = new Date(Date.now() + 3 * 3600e3), hr = mk.getUTCHours();\n  const dateAr = new Date().toLocaleDateString('ar-SA-u-ca-gregory-nu-latn', { timeZone: 'Asia/Riyadh', weekday: 'long', day: 'numeric', month: 'long' });\n  const hijri = new Date().toLocaleDateString('ar-SA-u-ca-islamic-umalqura-nu-latn', { timeZone: 'Asia/Riyadh', day: 'numeric', month: 'long', year: 'numeric' });\n  const delta = (cur, prev) => { if (!prev && !cur) return ''; if (!prev) return '<span class=\"dup\">جديد</span>'; const p = Math.round(((cur - prev) / prev) * 100); return `<span class=\"${p >= 0 ? 'dup' : 'ddown'}\">${p >= 0 ? '▲' : '▼'} ${Math.abs(p)}%</span>`; };\n  const sumArr = (x) => x.reduce((s, v) => s + v, 0);\n  const KPI = (n, l, sub, color, go) => `<div class=\"kpi\" ${go ? `data-go=\"${go}\"` : ''}><div class=\"l\">${l}</div><div class=\"n\" style=\"color:${color}\">${Number(n).toLocaleString('en')}</div><div class=\"s\">${sub || '&nbsp;'}</div></div>`;\n  const tasks = [\n    [k.eventDrafts, 'فعالية مسودة تنتظر النشر', 'events', 'var(--orangeDeep)'], [k.placeDrafts, 'مكان مسودة ينتظر النشر', 'drafts', 'var(--orangeDeep)'],\n    [k.communityPending, 'مشاركة تنتظر مراجعتك', 'community', 'var(--orange)'], [k.reported, 'بلاغ في المجتمع', 'community', 'var(--pinkDeep)'], [k.creports, 'بلاغ عميل على كوبون', 'merchants', 'var(--pinkDeep)'],\n    [k.merchantsPending, 'طلب تاجر جديد', 'merchants', 'var(--purple)'], [k.couponsPending, 'كوبون ينتظر الموافقة', 'merchants', 'var(--purple)'],\n    [k.photosPending, 'صورة زوار تنتظر', 'photos', 'var(--skyDeep)'], [k.suggPending, 'اقتراح من الزوار', 'suggest', 'var(--skyDeep)'],\n    [k.guidesPending, 'طلب «مرشد موثّق»', 'users', 'var(--green)'], [k.unanswered, 'سؤال بدون إجابة', 'community', 'var(--lilac)'],\n  ].filter((t) => t[0]);\n  const list = (rows, fmt, empty) => rows.length ? rows.map(fmt).join('') : `<div class=\"muted\" style=\"font-size:13px;padding:6px 0\">${empty}</div>`;\n  const noTrack = !a.all_time;\n  m.innerHTML = `\n  <div class=\"row\" style=\"align-items:flex-end;margin-bottom:18px\"><div class=\"grow\"><h1>${hr < 12 ? 'صباح الخير' : 'مساء الخير'} يا رامي</h1><p class=\"sub\" style=\"margin:0\">${dateAr} · ${hijri}</p></div>\n    <div class=\"row\"><button class=\"btn o\" id=\"addP\">+ مكان</button><button class=\"btn\" id=\"addE\">+ فعالية</button><button class=\"btn ghost\" data-go=\"messages\">رسالة للمستخدمين</button></div></div>\n  ${noTrack ? '<div class=\"hint\" style=\"margin-bottom:14px\">أرقام الاستخدام (النشطين، فتح التطبيق، المشاهدات، البحث) تبدأ تتجمع أول ما ينزل التطبيق الجديد للناس. الأرقام الحالية من تجاربك.</div>' : ''}\n  <div class=\"kpis\">\n    ${KPI(a.today, 'نشطين اليوم', 'أجهزة فتحت التطبيق', 'var(--green)')}\n    ${KPI(a.d7, 'نشطين آخر 7 أيام', delta(a.d7, a.prev7) + ' عن الأسبوع اللي قبله', 'var(--green)')}\n    ${KPI(a.d30, 'نشطين آخر 30 يوم', `${a.all_time.toLocaleString('en')} جهاز من البداية`, 'var(--green)')}\n    ${KPI(k.users, 'مستخدم مسجّل', `+${k.users7} هالأسبوع ${delta(k.users7, k.usersPrev7)}`, 'var(--purple)', 'users')}\n    ${KPI(sumArr(d.series.opens.slice(-7)), 'مرة فتحوا التطبيق (7 أيام)', '', 'var(--skyDeep)')}\n    ${KPI(k.places, 'مكان منشور', `${k.events} فعالية قادمة`, 'var(--orangeDeep)', 'places')}\n  </div>\n  <div class=\"dgrid\">\n    <div class=\"card\"><div class=\"row\"><b class=\"grow\">النشاط آخر 30 يوم</b><span class=\"lg\"><i style=\"background:#604C87\"></i>أجهزة نشطة</span><span class=\"lg\"><i style=\"background:#F89743\"></i>مرات الفتح</span></div>\n      <div style=\"margin-top:10px\">${chart2(d.series.active, d.series.opens)}</div>\n      <div class=\"row muted\" style=\"font-size:11px;direction:ltr;margin-top:4px\"><span>${d.series.from}</span><span class=\"grow\"></span><span>اليوم</span></div></div>\n    <div class=\"card\"><div class=\"row\"><b class=\"grow\">مهام تنتظرك</b><span class=\"muted\" style=\"font-size:12px\">${tasks.length ? tasks.reduce((s, t) => s + t[0], 0) + ' عنصر' : ''}</span></div>\n      <div style=\"margin-top:8px\">${tasks.length ? tasks.map(([n, l, go, c]) => `<div class=\"task\" data-go=\"${go}\"><b style=\"color:${c}\">${n}</b><span class=\"grow\">${l}</span><span class=\"muted\">←</span></div>`).join('') : '<div class=\"ok\">كل شي تمام، ما فيه شي ينتظرك ✓</div>'}</div></div>\n  </div>\n  <div class=\"dgrid3\">\n    <div class=\"card\"><b>أكثر الأماكن مشاهدة</b><span class=\"muted\" style=\"font-size:12px\"> · 7 أيام</span>\n      <div style=\"margin-top:8px\">${list(d.topPlaces, (r, i) => `<div class=\"li\" data-place=\"${r.id}\"><span class=\"rk\">${i + 1}</span><span class=\"grow\">${h(r.title || 'مكان #' + r.id)} <span class=\"muted\" style=\"font-size:12px\">${cityName(r.city)}</span></span><b>${r.n}</b></div>`, 'تبدأ تظهر بعد إطلاق التطبيق')}</div></div>\n    <div class=\"card\"><b>وش يدورون</b><span class=\"muted\" style=\"font-size:12px\"> · 30 يوم</span>\n      <div style=\"margin-top:8px\">${list(d.topSearch, (r) => `<div class=\"li\"><span class=\"grow\">${h(r.k)}</span><b>${r.n}</b></div>`, 'ما فيه بحث مسجّل للحين')}</div></div>\n    <div class=\"card\" style=\"border:2px solid var(--softOrange)\"><b>بحثوا وما لقوا</b><span class=\"muted\" style=\"font-size:12px\"> · فرص محتوى</span>\n      <div style=\"margin-top:8px\">${list(d.emptySearch, (r) => `<div class=\"li\"><span class=\"grow\">${h(r.k)}</span><b style=\"color:var(--orangeDeep)\">${r.n}</b><button class=\"mini\" style=\"background:var(--softOrange);color:var(--orangeDeep)\" data-newp=\"${h(r.k)}\">أضفه</button></div>`, 'ممتاز: كل اللي بحثوا عنه لقوه')}</div></div>\n  </div>\n  <div class=\"dgrid3\">\n    <div class=\"card\"><b>صحة المحتوى</b>\n      <div style=\"margin-top:8px\">\n        <div class=\"task\" data-go=\"nophoto\"><b style=\"color:var(--muted)\">${k.noPhoto}</b><span class=\"grow\">مكان بدون صورة</span><span class=\"muted\">←</span></div>\n        <div class=\"task\" data-go=\"nogeo\"><b style=\"color:var(--muted)\">${k.noGeo}</b><span class=\"grow\">مكان بدون موقع</span><span class=\"muted\">←</span></div>\n        <div class=\"task\" data-go=\"events\"><b style=\"color:var(--muted)\">${k.eventDraftsNoImg}</b><span class=\"grow\">فعالية مسودة بدون صورة</span><span class=\"muted\">←</span></div>\n      </div>\n      ${d.draftsSoon.length ? `<div class=\"warn\" style=\"margin-top:10px\"><b>مسودات تبدأ قريب وما انتشرت:</b>${d.draftsSoon.map((e) => `<div>• ${h(e.title)} · ${fmt(e.start)}</div>`).join('')}</div>` : ''}</div>\n    <div class=\"card\"><b>فعاليات هالأسبوع</b>\n      <div style=\"margin-top:8px\">${list(d.upcoming, (e) => `<div class=\"li\" data-ev=\"${e.id}\"><span class=\"grow\">${h(e.title)} <span class=\"muted\" style=\"font-size:12px\">${cityName(e.city)}</span></span><span class=\"muted\" style=\"font-size:12px\">${fmt(e.start)}</span></div>`, 'ما فيه فعاليات منشورة هالأسبوع')}</div></div>\n    <div class=\"card\"><b>المجتمع هالأسبوع</b>\n      <div class=\"mini-stats\">${[[k.posts7, 'سؤال ونصيحة'], [k.answers7, 'إجابة'], [k.reviews7, 'تقييم'], [k.visits7, 'زيارة مختومة'], [k.redeems7, 'كوبون استُخدم'], [k.unanswered, 'بدون إجابة']].map(([n, l]) => `<div><b>${n}</b><span>${l}</span></div>`).join('')}</div>\n      <div style=\"margin-top:8px\">${list(d.recent, (r) => `<div class=\"li\" style=\"font-size:13px\"><span class=\"grow\">${h(r.name || 'مستخدم')}: ${h(r.text.slice(0, 60))}</span></div>`, 'ما فيه مشاركات للحين')}</div></div>\n  </div>\n  <div class=\"row muted\" style=\"font-size:12px;gap:16px;margin-top:6px\">\n    <span>المنصات: ${d.platforms.length ? d.platforms.map((x) => `${({ ios: 'آيفون', android: 'أندرويد', web: 'ويب' })[x.k] || x.k} ${x.n}`).join(' · ') : '—'}</span>\n    <span>أجهزة الإشعارات: ${k.pushDevices}</span>\n    <span>آخر استيراد من قودبابر: ${d.lastSync ? fmt(new Date(d.lastSync.ts * 1000).toISOString()) + (d.lastSync.error ? ' (فشل)' : '') : '—'}</span>\n  </div>`;\n  $('#addP').onclick = () => editPlace(null);\n  $('#addE').onclick = () => editEvent(null);\n  m.querySelectorAll('[data-go]').forEach((el) => (el.onclick = () => {\n    const g = el.dataset.go;\n    if (g === 'drafts') { PF.status = 'draft'; VIEW = 'places'; } else if (g === 'nophoto') { PF.missing = 'photo'; VIEW = 'places'; } else if (g === 'nogeo') { PF.missing = 'geo'; VIEW = 'places'; } else VIEW = g;\n    render();\n  }));\n  m.querySelectorAll('[data-place]').forEach((el) => (el.onclick = async () => editPlace((await api('/admin/places/' + el.dataset.place)).place)));\n  m.querySelectorAll('[data-ev]').forEach((el) => (el.onclick = async () => editEvent((await api('/admin/events/' + el.dataset.ev)).event)));\n  m.querySelectorAll('[data-newp]').forEach((b) => (b.onclick = () => { editPlace(null); setTimeout(() => { const t = document.querySelector('#drawer [name=title], #drawer #title'); if (t) { t.value = b.dataset.newp; t.dispatchEvent(new Event('input')); } }, 80); }));\n}\n\n/* ——— الأماكن ——— */\nconst PF = { city: '', status: '', q: '', missing: '', page: 1 };\nasync function placesView() {\n  const m = $('#main');\n  m.innerHTML = `<div class=\"row\"><div class=\"grow\"><h1>الأماكن</h1><p class=\"sub\">الأماكن الجديدة تنحفظ مسودة، وما تظهر في التطبيق لين تضغط «انشر».</p></div><button class=\"btn o\" id=\"add\">+ مكان جديد</button></div>\n    <div class=\"filters\"><input class=\"in\" id=\"q\" placeholder=\"ابحث بالاسم أو الرقم\" value=\"${h(PF.q)}\">\n    <select class=\"in\" id=\"city\"><option value=\"\">كل المدن</option>${META.cities.map((c) => `<option value=\"${c.id}\" ${PF.city === c.id ? 'selected' : ''}>${c.name}</option>`).join('')}</select>\n    <select class=\"in\" id=\"status\"><option value=\"\">كل الحالات</option>${Object.entries(ST).map(([k, v]) => `<option value=\"${k}\" ${PF.status === k ? 'selected' : ''}>${v[0]}</option>`).join('')}</select>\n    <select class=\"in\" id=\"missing\"><option value=\"\">بدون فلتر</option><option value=\"photo\" ${PF.missing === 'photo' ? 'selected' : ''}>بدون صورة</option><option value=\"geo\" ${PF.missing === 'geo' ? 'selected' : ''}>بدون موقع</option></select></div>\n    <div id=\"res\" class=\"list\"><p class=\"muted\">لحظة...</p></div>`;\n  $('#add').onclick = () => editPlace(null);\n  let t; $('#q').oninput = (e) => { clearTimeout(t); t = setTimeout(() => { PF.q = e.target.value; PF.page = 1; loadPlaces(); }, 350); };\n  ['city', 'status', 'missing'].forEach((k) => ($('#' + k).onchange = (e) => { PF[k] = e.target.value; PF.page = 1; loadPlaces(); }));\n  loadPlaces();\n}\nasync function loadPlaces() {\n  const qs = new URLSearchParams(Object.entries(PF).filter(([, v]) => v)).toString();\n  const d = await api('/admin/places?' + qs);\n  const pages = Math.ceil(d.total / 30);\n  $('#res').innerHTML = `<div class=\"muted\" style=\"font-size:13px\">${d.total} مكان</div>` + (d.places.map((p) => `<div class=\"item\" data-id=\"${p.id}\">\n    ${p.thumb ? `<img src=\"${h(p.thumb)}\" loading=\"lazy\">` : '<div class=\"ph\">بدون صورة</div>'}\n    <div class=\"grow\"><div class=\"t\">${h(p.title)}</div><div class=\"m\">${cityName(p.city)} · ${p.kinds.map((k) => KIND[k] || k).join('، ') || 'بدون تصنيف'}${!p.lat ? ' · <span style=\"color:var(--pinkDeep)\">بدون موقع</span>' : ''}</div></div>\n    ${p.status === 'draft' ? `<button class=\"mini\" style=\"background:var(--softGreen);color:var(--green)\" data-pub=\"${p.id}\">انشر</button>` : ''}<span class=\"badge ${ST[p.status][1]}\">${ST[p.status][0]}</span></div>`).join('') || '<div class=\"empty\">ما فيه نتائج</div>')\n    + (pages > 1 ? `<div class=\"row\" style=\"justify-content:center;margin-top:10px\">${PF.page > 1 ? '<button class=\"btn ghost\" id=\"prev\">السابق</button>' : ''}<span class=\"muted\">${PF.page} من ${pages}</span>${PF.page < pages ? '<button class=\"btn ghost\" id=\"next\">التالي</button>' : ''}</div>` : '');\n  document.querySelectorAll('#res .item').forEach((el) => (el.onclick = async () => editPlace((await api('/admin/places/' + el.dataset.id)).place)));\n  document.querySelectorAll('#res [data-pub]').forEach((b) => (b.onclick = async (e) => { e.stopPropagation(); await api(`/admin/places/${b.dataset.pub}/status`, { method: 'POST', body: { status: 'live' } }); toast('انتشر'); loadPlaces(); }));\n  $('#prev') && ($('#prev').onclick = () => { PF.page--; loadPlaces(); });\n  $('#next') && ($('#next').onclick = () => { PF.page++; loadPlaces(); });\n}\n\n/* ——— أدوات النماذج ——— */\nfunction drawer(html) {\n  let d = $('#drawer');\n  if (!d) { d = document.createElement('div'); d.id = 'drawer'; d.className = 'drawer'; document.body.appendChild(d); d.onclick = (e) => { if (e.target === d) closeDrawer(); }; }\n  d.innerHTML = `<div class=\"sheet\">${html}</div>`; d.classList.add('on'); return d;\n}\nconst closeDrawer = () => $('#drawer')?.classList.remove('on');\nfunction imagesWidget(el, list, onChange) {\n  const draw = () => {\n    el.innerHTML = `<div class=\"imgs\">${list.map((u, i) => `<div class=\"im\" draggable=\"true\" data-i=\"${i}\" title=\"اسحبها لترتيب الصور\"><img src=\"${h(u)}\" draggable=\"false\">${i === 0 ? '<span class=\"cover\">الغلاف</span>' : `<button class=\"mk\" data-i=\"${i}\">اجعلها الغلاف</button>`}<button class=\"x\" data-i=\"${i}\" title=\"شيل\">×</button></div>`).join('')}\n      <button type=\"button\" class=\"up\" id=\"upBtn\">+ صورة<br><small>أو اسحبها هنا</small></button><input type=\"file\" accept=\"image/*\" multiple style=\"position:absolute;width:1px;height:1px;opacity:0;pointer-events:none\"></div>\n      <input class=\"in\" style=\"margin-top:8px\" placeholder=\"أو الصق رابط صورة واضغط Enter\">`;\n    el.querySelectorAll('.x').forEach((b) => (b.onclick = () => { list.splice(+b.dataset.i, 1); draw(); }));\n    let from = -1;\n    el.querySelectorAll('.im').forEach((im) => {\n      im.ondragstart = (e) => { from = +im.dataset.i; im.classList.add('dragging'); e.dataTransfer.effectAllowed = 'move'; e.dataTransfer.setData('text/plain', 'img'); };\n      im.ondragend = () => im.classList.remove('dragging');\n      im.ondragover = (e) => { if (from < 0) return; e.preventDefault(); e.stopPropagation(); im.classList.add('over'); };\n      im.ondragleave = () => im.classList.remove('over');\n      im.ondrop = (e) => { if (from < 0) return; e.preventDefault(); e.stopPropagation(); const to = +im.dataset.i; const [u] = list.splice(from, 1); list.splice(to, 0, u); from = -1; draw(); onChange && onChange(); };\n    });\n    el.querySelectorAll('.mk').forEach((b) => (b.onclick = () => { const [u] = list.splice(+b.dataset.i, 1); list.unshift(u); draw(); onChange && onChange(); }));\n    const fi = el.querySelector('input[type=file]');\n    el.querySelector('#upBtn').onclick = () => fi.click();\n    const upload = async (files) => {\n      for (const f of files) {\n        if (!/^image\\/(jpeg|png|webp)$/.test(f.type)) { toast('الصورة لازم JPG أو PNG أو WEBP (صور الآيفون HEIC حوّلها أول)'); continue; }\n        toast('يرفع الصورة...');\n        try { const r = await api('/admin/upload', { method: 'POST', body: f, headers: { 'Content-Type': f.type } }); list.push(r.url); draw(); onChange && onChange(); toast('انرفعت'); } catch (er) { toast(errMsg(er)); }\n      }\n    };\n    fi.onchange = (e) => upload([...e.target.files]);\n    const zone = el.querySelector('.imgs');\n    zone.ondragover = (e) => { e.preventDefault(); zone.style.outline = '2px dashed var(--orange)'; };\n    zone.ondragleave = () => (zone.style.outline = '');\n    zone.ondrop = (e) => { e.preventDefault(); zone.style.outline = ''; if (e.dataTransfer.files.length) upload([...e.dataTransfer.files]); };\n    el.querySelector('input.in').onkeydown = (e) => { if (e.key === 'Enter' && /^https?:\\/\\//.test(e.target.value)) { e.preventDefault(); list.push(e.target.value.trim()); draw(); } };\n  };\n  draw();\n}\nfunction chipsWidget(el, options, selected, allowNew) {\n  const all = [...new Set([...options, ...selected])];\n  const draw = () => {\n    el.innerHTML = `<div class=\"chips\">${all.map((o) => `<span class=\"chip ${selected.includes(o) ? 'on' : ''}\" data-o=\"${h(o)}\">${h(o)}</span>`).join('')}</div>${allowNew ? '<input class=\"in\" style=\"margin-top:8px\" placeholder=\"تصنيف جديد؟ اكتبه واضغط Enter\">' : ''}`;\n    el.querySelectorAll('.chip').forEach((c) => (c.onclick = () => { const o = c.dataset.o; const i = selected.indexOf(o); i >= 0 ? selected.splice(i, 1) : selected.push(o); draw(); }));\n    const inp = el.querySelector('input'); if (inp) inp.onkeydown = (e) => { if (e.key === 'Enter' && e.target.value.trim()) { e.preventDefault(); const v = e.target.value.trim(); all.push(v); selected.push(v); draw(); } };\n  };\n  draw();\n}\n/** يطلع الإحداثيات من رابط قوقل ماب أو من «24.46, 39.61» */\nfunction parseGeo(s) {\n  const m = String(s).match(/@(-?\\d+\\.\\d+),(-?\\d+\\.\\d+)/) || String(s).match(/[?&]q=(-?\\d+\\.\\d+),(-?\\d+\\.\\d+)/) || String(s).match(/!3d(-?\\d+\\.\\d+)!4d(-?\\d+\\.\\d+)/) || String(s).match(/^\\s*(-?\\d+\\.\\d+)\\s*[,،]\\s*(-?\\d+\\.\\d+)\\s*$/);\n  return m ? [+m[1], +m[2]] : null;\n}\n/** الموقع: بحث بالاسم (OpenStreetMap) + خريطة بدبوس تسحبه + لصق رابط قوقل ماب */\nfunction geoWidget(box, lat, lng, cityFn, addrEl, onSet) {\n  box.innerHTML = `<div class=\"geo\"><input class=\"in\" id=\"gq\" placeholder=\"اكتب اسم المكان... أو الصق رابط قوقل ماب\" autocomplete=\"off\"><div class=\"sug\" id=\"sug\"></div>\n    <input type=\"hidden\" id=\"geo\" value=\"${lat ? lat + ', ' + lng : ''}\"><div class=\"map\" id=\"gmap\"></div><small id=\"geoMsg\" class=\"muted\"></small></div>`;\n  const q = $('#gq', box), sug = $('#sug', box), out = $('#geo', box), msg = $('#geoMsg', box);\n  const center = () => { const c = META.cities.find((x) => x.id === cityFn()); return c ? [c.lat, c.lng] : [24.2, 44.5]; };\n  if (!window.L) { $('#gmap', box).remove(); window.L = { map: () => ({ setView() { return this; }, on() {}, invalidateSize() {}, addLayer() {}, removeLayer() {} }), tileLayer: () => ({ addTo() { return this; }, on() {} }), marker: () => ({ addTo() { return this; }, on() {}, setLatLng() {} }) }; }\n  const map = L.map($('#gmap', box), { zoomControl: true, attributionControl: true }).setView(lat ? [lat, lng] : center(), lat ? 16 : (cityFn() ? 11 : 5));\n  // خريطة OpenStreetMap، ولو رفضت نحوّل تلقائياً لخرائط Esri\n  let fails = 0, alt = false;\n  const osm = L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19, attribution: '© OpenStreetMap' }).addTo(map);\n  osm.on && osm.on('tileerror', () => { if (++fails > 2 && !alt) { alt = true; map.removeLayer(osm); L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', { maxZoom: 19, attribution: 'Tiles © Esri' }).addTo(map); } });\n  let pin = null;\n  const set = (la, ln, zoom) => {\n    la = +(+la).toFixed(6); ln = +(+ln).toFixed(6);\n    out.value = la + ', ' + ln;\n    if (!pin) { pin = L.marker([la, ln], { draggable: true }).addTo(map); pin.on('dragend', () => { const p = pin.getLatLng(); set(p.lat, p.lng); }); } else pin.setLatLng([la, ln]);\n    if (zoom) map.setView([la, ln], zoom);\n    msg.innerHTML = `✓ ${la}, ${ln} · <a target=\"_blank\" href=\"https://maps.google.com/?q=${la},${ln}\">تأكد في قوقل ماب</a> · تقدر تسحب الدبوس لو مو مضبوط`;\n    onSet && onSet(la, ln);\n  };\n  if (lat) set(lat, lng); else msg.textContent = 'اكتب الاسم واختر من القائمة، أو اضغط على الخريطة مكان المكان';\n  setTimeout(() => map.invalidateSize(), 250);\n  map.on('click', (ev) => set(ev.latlng.lat, ev.latlng.lng));\n  let t, last = '';\n  q.oninput = () => {\n    const v = q.value.trim();\n    const g = parseGeo(v);\n    if (g) { sug.style.display = 'none'; set(g[0], g[1], 17); return; }\n    if (/^https?:\\/\\//.test(v)) { sug.style.display = 'none'; msg.innerHTML = '<span style=\"color:var(--pinkDeep)\">ما قدرت أقرا الرابط. الروابط المختصرة (maps.app.goo.gl) افتحها بالمتصفح أول وانسخ الرابط الطويل، أو اكتب اسم المكان.</span>'; return; }\n    clearTimeout(t);\n    if (v.length < 3) { sug.style.display = 'none'; return; }\n    t = setTimeout(async () => {\n      if (v === last) return; last = v;\n      const c = center(), b = 1.2;\n      const url = `https://nominatim.openstreetmap.org/search?format=jsonv2&limit=6&countrycodes=sa&accept-language=ar&q=${encodeURIComponent(v)}` + (cityFn() ? `&viewbox=${c[1] - b},${c[0] + b},${c[1] + b},${c[0] - b}` : '');\n      try {\n        const r = await fetch(url).then((x) => x.json());\n        sug.innerHTML = r.length ? r.map((x, i) => `<div data-i=\"${i}\"><b>${h(x.name || x.display_name.split('،')[0].split(',')[0])}</b><span>${h(x.display_name)}</span></div>`).join('') : '<div style=\"cursor:default\"><span>ما لقيت شي. جرّب اسم ثاني، أو اضغط على الخريطة مكان المكان.</span></div>';\n        sug.style.display = 'block';\n        sug.querySelectorAll('[data-i]').forEach((el) => (el.onclick = () => {\n          const x = r[+el.dataset.i]; sug.style.display = 'none'; q.value = x.name || '';\n          set(x.lat, x.lon, 17);\n          if (addrEl && !addrEl.value) addrEl.value = x.display_name.split(/[،,]/).slice(0, 3).join('،').trim();\n        }));\n      } catch { msg.textContent = 'البحث ما اشتغل الحين. اضغط على الخريطة مكان المكان.'; }\n    }, 600);\n  };\n  q.onblur = () => setTimeout(() => (sug.style.display = 'none'), 200);\n}\nconst plainBody = (html) => String(html || '').replace(/<br\\s*\\/?>/gi, '\\n').replace(/<\\/p>\\s*<p[^>]*>/gi, '\\n\\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').trim();\n\n/* ——— محرّر المكان ——— */\nfunction editPlace(p) {\n  const isNew = !p;\n  p = p || { city: PF.city || '', title: '', title_en: '', cats: [], kinds: [], summary: '', body: '', images: [], lat: null, lng: null, address: '', phone: '', website: '', email: '', status: 'draft' };\n  const images = [...p.images], cats = [...p.cats], kinds = [...p.kinds];\n  const d = drawer(`<div class=\"row\"><div class=\"grow\"><h2>${isNew ? 'مكان جديد' : h(p.title)}</h2><div class=\"m muted\">${isNew ? 'بينحفظ مسودة' : `رقم ${p.id} · <span class=\"badge ${ST[p.status][1]}\">${ST[p.status][0]}</span>${p.fromPanel ? ' <span class=\"badge b-panel\">معدّل من اللوحة</span>' : ''}`}</div></div><button class=\"btn ghost\" id=\"x\">إغلاق</button></div>\n    <div id=\"prevBox\" style=\"display:none\"></div>\n    <div class=\"two\"><div class=\"f\"><label>الاسم بالعربي *</label><input class=\"in\" id=\"title\" value=\"${h(p.title)}\"></div><div class=\"f\"><label>الاسم بالإنجليزي</label><input class=\"in\" id=\"title_en\" value=\"${h(p.title_en)}\" dir=\"ltr\"></div></div>\n    <div id=\"dup\"></div>\n    <div class=\"f\"><label>المدينة *</label><select class=\"in\" id=\"city\"><option value=\"\">اختر</option>${META.cities.map((c) => `<option value=\"${c.id}\" ${p.city === c.id ? 'selected' : ''}>${c.name}</option>`).join('')}</select></div>\n    <div class=\"f\"><label>النوع في التطبيق</label><div id=\"kinds\"></div><small>يحدد لون وأيقونة المكان في الخريطة والفلاتر</small></div>\n    <div class=\"f\"><label>التصنيفات</label><div id=\"cats\"></div></div>\n    <div class=\"f\"><label>الصور</label><div id=\"imgs\"></div><small>أول صورة هي الغلاف</small></div>\n    <div class=\"f\"><label>وصف قصير</label><input class=\"in\" id=\"summary\" value=\"${h(p.summary)}\" maxlength=\"400\"><small>يطلع في القوائم ونتائج البحث</small></div>\n    <div class=\"f\"><label>عن المكان</label><textarea class=\"in\" id=\"body\">${h(plainBody(p.body))}</textarea><small>سطر فاضي بين الفقرات</small></div>\n    <div class=\"f\"><label>الموقع على الخريطة</label><div id=\"geoBox\"></div></div>\n    <div class=\"f\"><label>العنوان</label><input class=\"in\" id=\"address\" value=\"${h(p.address)}\"></div>\n    <div class=\"two\"><div class=\"f\"><label>الجوال</label><input class=\"in\" id=\"phone\" value=\"${h(p.phone)}\" dir=\"ltr\"></div><div class=\"f\"><label>الموقع الإلكتروني</label><input class=\"in\" id=\"website\" value=\"${h(p.website)}\" dir=\"ltr\"></div></div>\n    <div class=\"bar\"><button class=\"btn\" id=\"save\">حفظ</button>\n      ${p.status !== 'live' ? '<button class=\"btn g\" id=\"pub\">حفظ وانشر</button>' : '<button class=\"btn ghost\" id=\"unpub\">رجّعه مسودة</button>'}\n      ${!isNew && p.status !== 'hidden' ? '<button class=\"btn ghost\" id=\"hide\" style=\"color:var(--pinkDeep)\">إخفاء</button>' : ''}<button class=\"btn ghost\" id=\"pv\">معاينة في التطبيق</button></div>`);\n  /* معاينة: شكل بطاقة المكان في التطبيق */\n  const drawPrev = () => {\n    const box = $('#prevBox', d); if (box.style.display === 'none') return;\n    const c = collect();\n    box.innerHTML = `<div class=\"hint\">هذا شكل المكان تقريباً في التطبيق</div><div class=\"prev\"><div class=\"cv\" style=\"background-image:url('${h(images[0] || '')}')\">${c.kinds[0] ? `<b>${KIND[c.kinds[0]]}</b>` : ''}</div>\n      <div class=\"bd\"><h3>${h(c.title || 'اسم المكان')}</h3><div class=\"muted\" style=\"font-size:13px\">${cityName(c.city)}${c.lat ? ' · على الخريطة ✓' : ' · <span style=\"color:var(--pinkDeep)\">بدون موقع</span>'}</div>\n      <p>${h(c.summary || 'الوصف القصير يطلع هنا')}</p><p>${h(plainBody(c.body).slice(0, 220))}${plainBody(c.body).length > 220 ? '…' : ''}</p>\n      ${images.length > 1 ? `<p>${images.length} صور</p>` : ''}</div></div>`;\n  };\n  $('#pv', d).onclick = () => { const box = $('#prevBox', d); box.style.display = box.style.display === 'none' ? 'block' : 'none'; drawPrev(); if (box.style.display === 'block') d.querySelector('.sheet').scrollTo({ top: 0, behavior: 'smooth' }); };\n  d.querySelector('.sheet').addEventListener('input', () => drawPrev());\n  /* تنبيه التكرار */\n  let dupT;\n  const checkDup = () => { clearTimeout(dupT); dupT = setTimeout(async () => {\n    const c = collect(); if (!c.title && !c.lat) return;\n    const r = await api('/admin/places/similar?' + new URLSearchParams({ title: c.title, city: c.city, lat: c.lat || '', lng: c.lng || '', id: p.id || '' })).catch(() => ({ similar: [] }));\n    $('#dup', d).innerHTML = r.similar.length ? `<div class=\"warn\">انتبه، يمكن المكان موجود: ${r.similar.map((x) => `<a href=\"#\" data-sim=\"${x.id}\">${h(x.title)}</a> (${cityName(x.city)} · ${x.why} · ${ST[x.status][0]})`).join('، ')}</div>` : '';\n    $('#dup', d).querySelectorAll('[data-sim]').forEach((a) => (a.onclick = async (e) => { e.preventDefault(); if (confirm('تفتح المكان الموجود؟ التعديلات اللي هنا ما تنحفظ.')) editPlace((await api('/admin/places/' + a.dataset.sim)).place); }));\n  }, 500); };\n  $('#title', d).addEventListener('change', checkDup); $('#city', d).addEventListener('change', checkDup);\n  imagesWidget($('#imgs', d), images, drawPrev);\n  chipsWidget($('#cats', d), META.placeCats, cats, true);\n  const kEl = $('#kinds', d);\n  const drawK = () => { kEl.innerHTML = `<div class=\"chips\">${META.kinds.map((k) => `<span class=\"chip ${kinds.includes(k) ? 'on' : ''}\" data-k=\"${k}\">${KIND[k]}</span>`).join('')}</div>`; kEl.querySelectorAll('.chip').forEach((c) => (c.onclick = () => { const i = kinds.indexOf(c.dataset.k); i >= 0 ? kinds.splice(i, 1) : kinds.push(c.dataset.k); drawK(); drawPrev(); })); };\n  drawK();\n  geoWidget($('#geoBox', d), p.lat, p.lng, () => $('#city', d).value, $('#address', d), () => { if (isNew) checkDup(); drawPrev(); });\n  $('#x', d).onclick = closeDrawer;\n  function collect() { const g = parseGeo($('#geo', d)?.value || ''); return { title: $('#title', d).value, title_en: $('#title_en', d).value, city: $('#city', d).value, cats, kinds, images, summary: $('#summary', d).value, body: $('#body', d).value, lat: g?.[0] ?? null, lng: g?.[1] ?? null, address: $('#address', d).value, phone: $('#phone', d).value, website: $('#website', d).value }; }\n  const save = async (status) => {\n    try {\n      const r = await api(isNew ? '/admin/places' : '/admin/places/' + p.id, { method: isNew ? 'POST' : 'PUT', body: collect() });\n      if (status) await api(`/admin/places/${r.place.id}/status`, { method: 'POST', body: { status } });\n      toast(status === 'live' ? 'انحفظ وانتشر' : status === 'draft' ? 'رجع مسودة' : 'انحفظ'); closeDrawer(); VIEW === 'places' ? loadPlaces() : render();\n    } catch (e) { toast(errMsg(e)); }\n  };\n  $('#save', d).onclick = () => save();\n  $('#pub', d) && ($('#pub', d).onclick = () => save('live'));\n  $('#unpub', d) && ($('#unpub', d).onclick = () => save('draft'));\n  $('#hide', d) && ($('#hide', d).onclick = async () => { if (!confirm('تخفي المكان من التطبيق؟ تقدر ترجعه بعدين.')) return; await api(`/admin/places/${p.id}/status`, { method: 'POST', body: { status: 'hidden' } }); toast('انخفى'); closeDrawer(); VIEW === 'places' ? loadPlaces() : render(); });\n}\n\n/* ——— الفعاليات ——— */\nconst EF = { when: 'upcoming', status: '', city: '', q: '' };\n// التاريخ يندخل بتوقيت مكة، وينحفظ UTC\nconst toLocal = (iso) => { if (!iso) return ''; const d = new Date(new Date(iso).getTime() + 3 * 3600e3); return d.toISOString().slice(0, 16); };\nconst fromLocal = (v) => (v ? new Date(v + ':00+03:00').toISOString() : '');\nconst fmt = (iso) => { if (!iso) return ''; return new Date(iso).toLocaleString('ar-SA-u-ca-gregory-nu-latn', { timeZone: 'Asia/Riyadh', day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' }); };\nasync function eventsView() {\n  const m = $('#main');\n  m.innerHTML = `<div class=\"row\"><div class=\"grow\"><h1>الفعاليات</h1><p class=\"sub\">الفعالية الجديدة تنحفظ مسودة. اربطها بموسم من التصنيفات عشان تطلع في صفحة الموسم.</p></div><button class=\"btn o\" id=\"add\">+ فعالية جديدة</button></div>\n    <div class=\"tabs\">${[['upcoming', 'القادمة'], ['past', 'السابقة'], ['all', 'الكل']].map(([k, t]) => `<button data-w=\"${k}\" class=\"${EF.when === k ? 'on' : ''}\">${t}</button>`).join('')}</div>\n    <div class=\"filters\"><input class=\"in\" id=\"q\" placeholder=\"ابحث بالاسم أو التصنيف\" value=\"${h(EF.q)}\">\n    <select class=\"in\" id=\"city\"><option value=\"\">كل المدن</option>${META.cities.map((c) => `<option value=\"${c.id}\" ${EF.city === c.id ? 'selected' : ''}>${c.name}</option>`).join('')}</select>\n    <select class=\"in\" id=\"status\"><option value=\"\">كل الحالات</option>${Object.entries(ST).map(([k, v]) => `<option value=\"${k}\" ${EF.status === k ? 'selected' : ''}>${v[0]}</option>`).join('')}</select></div>\n    <div id=\"res\" class=\"list\"></div>`;\n  $('#add').onclick = () => editEvent(null);\n  m.querySelectorAll('[data-w]').forEach((b) => (b.onclick = () => { EF.when = b.dataset.w; eventsView(); }));\n  let t; $('#q').oninput = (e) => { clearTimeout(t); t = setTimeout(() => { EF.q = e.target.value; loadEvents(); }, 350); };\n  ['city', 'status'].forEach((k) => ($('#' + k).onchange = (e) => { EF[k] = e.target.value; loadEvents(); }));\n  loadEvents();\n}\nasync function loadEvents() {\n  const d = await api('/admin/events?' + new URLSearchParams(Object.entries(EF).filter(([, v]) => v)));\n  $('#res').innerHTML = d.events.map((e) => `<div class=\"item\" data-id=\"${e.id}\">${e.thumb ? `<img src=\"${h(e.thumb)}\" loading=\"lazy\">` : '<div class=\"ph\">بدون صورة</div>'}\n    <div class=\"grow\"><div class=\"t\">${h(e.title)}</div><div class=\"m\">${fmt(e.start)}${e.end ? ' ← ' + fmt(e.end) : ''} · ${cityName(e.city)}</div><div class=\"m\">${e.cats.map(h).join('، ')}</div></div>\n    <span class=\"badge ${ST[e.status][1]}\">${ST[e.status][0]}</span></div>`).join('') || '<div class=\"empty\">ما فيه فعاليات</div>';\n  document.querySelectorAll('#res .item').forEach((el) => (el.onclick = async () => editEvent((await api('/admin/events/' + el.dataset.id)).event)));\n}\nfunction editEvent(e) {\n  const isNew = !e;\n  e = e || { title: '', summary: '', body: '', images: [], start: '', end: '', all_day: false, cats: [], city: '', lat: null, lng: null, address: '', tickets: '', link: '', status: 'draft' };\n  const images = [...e.images], cats = [...e.cats];\n  const d = drawer(`<div class=\"row\"><div class=\"grow\"><h2>${isNew ? 'فعالية جديدة' : h(e.title)}</h2><div class=\"m muted\">${isNew ? 'بتنحفظ مسودة' : `رقم ${e.id} · <span class=\"badge ${ST[e.status][1]}\">${ST[e.status][0]}</span>`}</div></div><button class=\"btn ghost\" id=\"x\">إغلاق</button></div>\n    <div class=\"f\"><label>اسم الفعالية *</label><input class=\"in\" id=\"title\" value=\"${h(e.title)}\"></div>\n    <div class=\"two\"><div class=\"f\"><label>تبدأ * (بتوقيت مكة)</label><input class=\"in\" type=\"datetime-local\" id=\"start\" value=\"${toLocal(e.start)}\"></div><div class=\"f\"><label>تنتهي</label><input class=\"in\" type=\"datetime-local\" id=\"end\" value=\"${toLocal(e.end)}\"></div></div>\n    <div class=\"f\"><label style=\"display:flex;gap:8px;align-items:center;font-weight:600\"><input type=\"checkbox\" id=\"all_day\" ${e.all_day ? 'checked' : ''}> طول اليوم (بدون ساعة محددة)</label></div>\n    <div class=\"f\"><label>الموسم</label><div id=\"season\"></div><small>الفعاليات اللي تحمل اسم الموسم تطلع في صفحته في التطبيق</small></div>\n    <div class=\"f\"><label>النوع</label><div id=\"cats\"></div></div>\n    <div class=\"f\"><label>الصور</label><div id=\"imgs\"></div></div>\n    <div class=\"f\"><label>وصف قصير</label><input class=\"in\" id=\"summary\" value=\"${h(e.summary)}\" maxlength=\"400\"></div>\n    <div class=\"f\"><label>التفاصيل</label><textarea class=\"in\" id=\"body\">${h(plainBody(e.body))}</textarea></div>\n    <div class=\"two\"><div class=\"f\"><label>المدينة</label><select class=\"in\" id=\"city\"><option value=\"\">تلقائي من الموقع</option>${META.cities.map((c) => `<option value=\"${c.id}\" ${e.city === c.id ? 'selected' : ''}>${c.name}</option>`).join('')}</select></div>\n    <div class=\"f\"><label>المكان (العنوان)</label><input class=\"in\" id=\"address\" value=\"${h(e.address)}\" placeholder=\"بوليفارد سيتي، الرياض\"><small>أول جزء قبل الفاصلة يصير «منطقة الموسم»</small></div></div>\n    <div class=\"f\"><label>الموقع على الخريطة</label><div id=\"geoBox\"></div></div>\n    <div class=\"two\"><div class=\"f\"><label>رابط التذاكر</label><input class=\"in\" id=\"tickets\" dir=\"ltr\" value=\"${h(e.tickets)}\"></div><div class=\"f\"><label>رابط الفعالية</label><input class=\"in\" id=\"link\" dir=\"ltr\" value=\"${h(e.link)}\"></div></div>\n    <div class=\"bar\"><button class=\"btn\" id=\"save\">حفظ</button>${e.status !== 'live' ? '<button class=\"btn g\" id=\"pub\">حفظ وانشر</button>' : '<button class=\"btn ghost\" id=\"unpub\">رجّعها مسودة</button>'}\n      ${!isNew && e.status !== 'hidden' ? '<button class=\"btn ghost\" id=\"hide\" style=\"color:var(--pinkDeep)\">إخفاء</button>' : ''}${!isNew ? '<button class=\"btn ghost\" id=\"dup\">نسخة منها</button>' : ''}</div>`);\n  imagesWidget($('#imgs', d), images);\n  const seasonSel = cats.filter((c) => /^(موسم|لحظات)/.test(c)), typeSel = cats.filter((c) => !/^(موسم|لحظات)/.test(c));\n  chipsWidget($('#season', d), [...new Set([...SEASONS, ...META.eventCats.filter((c) => /^(موسم|لحظات)/.test(c))])], seasonSel, true);\n  chipsWidget($('#cats', d), [...new Set([...EV_TYPES, ...META.eventCats.filter((c) => !/^(موسم|لحظات)/.test(c))])], typeSel, true);\n  geoWidget($('#geoBox', d), e.lat, e.lng, () => $('#city', d).value, $('#address', d));\n  $('#x', d).onclick = closeDrawer;\n  const collect = () => { const g = parseGeo($('#geo', d).value); return { title: $('#title', d).value, start: fromLocal($('#start', d).value), end: fromLocal($('#end', d).value), all_day: $('#all_day', d).checked, cats: [...seasonSel, ...typeSel], images, summary: $('#summary', d).value, body: $('#body', d).value, city: $('#city', d).value, address: $('#address', d).value, lat: g?.[0] ?? null, lng: g?.[1] ?? null, tickets: $('#tickets', d).value, link: $('#link', d).value }; };\n  const save = async (status, asNew) => {\n    try {\n      const r = await api(isNew || asNew ? '/admin/events' : '/admin/events/' + e.id, { method: isNew || asNew ? 'POST' : 'PUT', body: collect() });\n      if (status) await api(`/admin/events/${r.event.id}/status`, { method: 'POST', body: { status } });\n      toast(asNew ? 'انحفظت نسخة جديدة كمسودة' : status === 'live' ? 'انحفظت وانتشرت' : 'انحفظت'); closeDrawer(); VIEW === 'events' ? loadEvents() : render();\n      if (asNew) editEvent(r.event);\n    } catch (er) { toast(errMsg(er)); }\n  };\n  $('#save', d).onclick = () => save();\n  $('#pub', d) && ($('#pub', d).onclick = () => save('live'));\n  $('#unpub', d) && ($('#unpub', d).onclick = () => save('draft'));\n  $('#dup', d) && ($('#dup', d).onclick = () => save(null, true));\n  $('#hide', d) && ($('#hide', d).onclick = async () => { if (!confirm('تخفي الفعالية من التطبيق؟')) return; await api(`/admin/events/${e.id}/status`, { method: 'POST', body: { status: 'hidden' } }); toast('انخفت'); closeDrawer(); VIEW === 'events' ? loadEvents() : render(); });\n}\n\n/* ——— المواسم ——— */\nconst SEASON_COLOR = { 'موسم الرياض': 'var(--purple)', 'موسم جدة': 'var(--skyDeep)', 'موسم الدرعية': 'var(--orangeDeep)', 'لحظات العلا': 'var(--pinkDeep)' };\nasync function seasonsView() {\n  const m = $('#main');\n  m.innerHTML = `<div class=\"row\"><div class=\"grow\"><h1>المواسم</h1><p class=\"sub\">الموسم يتكوّن من الفعاليات اللي تحمل اسمه. أضف فعالية واختر الموسم، وتطلع تلقائياً في صفحته في التطبيق.</p></div><button class=\"btn o\" id=\"add\">+ فعالية لموسم</button></div><div id=\"res\" class=\"list\"><p class=\"muted\">لحظة...</p></div>`;\n  $('#add').onclick = () => editEvent(null);\n  const d = await api('/admin/seasons');\n  const now = new Date().toISOString();\n  $('#res').innerHTML = d.seasons.map((x) => {\n    const st = x.end < now ? 'انتهى' : x.start > now ? 'يبدأ ' + fmt(x.start) : 'شغّال الحين';\n    return `<div class=\"season\" data-n=\"${h(x.name)}\" style=\"border-right-color:${SEASON_COLOR[x.name] || 'var(--lilac)'}\"><div class=\"row\"><b class=\"grow\" style=\"font-size:18px\">${h(x.name)}</b><span class=\"badge ${x.end < now ? 'b-hidden' : 'b-live'}\">${st}</span></div>\n      <div class=\"m muted\" style=\"margin-top:6px\">${x.live} فعالية منشورة${x.drafts ? ` · ${x.drafts} مسودة` : ''} · من ${fmt(x.start)} إلى ${fmt(x.end)}</div></div>`;\n  }).join('') || '<div class=\"empty\">ما فيه مواسم. أضف فعالية واختر لها موسم.</div>';\n  m.querySelectorAll('[data-n]').forEach((el) => (el.onclick = () => { EF.q = el.dataset.n; EF.when = 'all'; VIEW = 'events'; render(); }));\n}\n\n/* ——— مختارات الأسبوع ——— */\nconst SEAS = { a: 'طول السنة', w: 'الشتاء', s: 'الصيف' };\nasync function weeklyView() {\n  const m = $('#main');\n  m.innerHTML = '<p class=\"muted\">لحظة...</p>';\n  const d = await api('/admin/weekly');\n  const pool = d.pool;\n  const draw = () => {\n    m.innerHTML = `<div class=\"row\"><div class=\"grow\"><h1>مختارات الأسبوع</h1><p class=\"sub\">قائمة الأماكن اللي يختار منها التطبيق كل أسبوع 5 أماكن من مدن مختلفة. المميّزة ★ تطلع أول. «الشتاء» تطلع من نوفمبر لمارس، و«الصيف» من مايو لسبتمبر.</p></div><button class=\"btn g\" id=\"saveW\">حفظ القائمة</button></div>\n      <div class=\"card\" style=\"margin-bottom:14px\"><b>أضف مكان</b><input class=\"in\" id=\"wq\" placeholder=\"ابحث باسم المكان\" style=\"margin-top:8px\"><div id=\"wres\" class=\"list\" style=\"margin-top:8px\"></div></div>\n      <div class=\"muted\" style=\"font-size:13px;margin-bottom:8px\">${pool.length} مكان في القائمة</div>\n      <div class=\"list\">${pool.map((x, i) => `<div class=\"item\" style=\"cursor:default\">${x.thumb ? `<img src=\"${h(x.thumb)}\" loading=\"lazy\">` : '<div class=\"ph\">بدون صورة</div>'}\n        <div class=\"grow\"><div class=\"t\">${x.x ? '★ ' : ''}${h(x.title)}</div><div class=\"m\">${cityName(x.city)}${x.status !== 'live' ? ' · <span style=\"color:var(--pinkDeep)\">مو منشور</span>' : ''}</div></div>\n        <select class=\"in\" style=\"width:auto\" data-s=\"${i}\">${Object.entries(SEAS).map(([k, v]) => `<option value=\"${k}\" ${x.s === k ? 'selected' : ''}>${v}</option>`).join('')}</select>\n        <button class=\"mini\" style=\"background:var(--softOrange);color:var(--orangeDeep)\" data-x=\"${i}\">${x.x ? 'شيل التمييز' : '★ ميّزه'}</button>\n        <button class=\"mini\" style=\"background:var(--chip);color:var(--pinkDeep)\" data-r=\"${i}\">شيل</button></div>`).join('')}</div>`;\n    m.querySelectorAll('[data-s]').forEach((el) => (el.onchange = () => { pool[+el.dataset.s].s = el.value; }));\n    m.querySelectorAll('[data-x]').forEach((el) => (el.onclick = () => { const x = pool[+el.dataset.x]; x.x ? delete x.x : (x.x = 1); draw(); }));\n    m.querySelectorAll('[data-r]').forEach((el) => (el.onclick = () => { pool.splice(+el.dataset.r, 1); draw(); }));\n    $('#saveW').onclick = async () => { await api('/admin/weekly', { method: 'POST', body: { pool: pool.map(({ id, s, x }) => (x ? { id, s, x: 1 } : { id, s })) } }); toast('انحفظت القائمة'); };\n    let t; $('#wq').oninput = (e) => { clearTimeout(t); t = setTimeout(async () => {\n      const v = e.target.value.trim(); if (v.length < 2) { $('#wres').innerHTML = ''; return; }\n      const r = await api('/admin/places?status=live&q=' + encodeURIComponent(v));\n      $('#wres').innerHTML = r.places.slice(0, 6).map((p) => `<div class=\"item\" data-add=\"${p.id}\" data-t=\"${h(p.title)}\" data-c=\"${p.city}\" data-th=\"${h(p.thumb)}\"><div class=\"grow\"><div class=\"t\">${h(p.title)}</div><div class=\"m\">${cityName(p.city)}</div></div>${pool.some((x) => x.id === p.id) ? '<span class=\"badge b-live\">موجود</span>' : '<span class=\"mini\" style=\"background:var(--purple);color:#fff\">+ أضف</span>'}</div>`).join('') || '<div class=\"muted\">ما لقيت</div>';\n      $('#wres').querySelectorAll('[data-add]').forEach((el) => (el.onclick = () => { const id = +el.dataset.add; if (pool.some((x) => x.id === id)) return; pool.unshift({ id, s: 'a', title: el.dataset.t, city: el.dataset.c, thumb: el.dataset.th, status: 'live' }); draw(); toast('انضاف — اضغط «حفظ القائمة»'); }));\n    }, 350); };\n  };\n  draw();\n}\n\n/* ——— الأخبار والمقالات ——— */\nasync function articlesView() {\n  const m = $('#main');\n  m.innerHTML = `<div class=\"row\"><div class=\"grow\"><h1>الأخبار والمقالات</h1><p class=\"sub\">آخر 3 أخبار تطلع في الصفحة الرئيسية للتطبيق. الجديد ينحفظ مسودة.</p></div><button class=\"btn o\" id=\"add\">+ خبر جديد</button></div><div id=\"res\" class=\"list\"><p class=\"muted\">لحظة...</p></div>`;\n  $('#add').onclick = () => editArticle(null);\n  const d = await api('/admin/articles');\n  $('#res').innerHTML = d.articles.map((a) => `<div class=\"item\" data-id=\"${a.id}\">${a.thumb ? `<img src=\"${h(a.thumb)}\" loading=\"lazy\">` : '<div class=\"ph\">بدون صورة</div>'}\n    <div class=\"grow\"><div class=\"t\">${h(a.title)}</div><div class=\"m\">${fmt(a.date)}${a.author ? ' · ' + h(a.author) : ''}</div></div><span class=\"badge ${ST[a.status][1]}\">${ST[a.status][0]}</span></div>`).join('') || '<div class=\"empty\">ما فيه أخبار</div>';\n  m.querySelectorAll('[data-id]').forEach((el) => (el.onclick = async () => editArticle((await api('/admin/articles/' + el.dataset.id)).article)));\n}\nfunction editArticle(a) {\n  const isNew = !a;\n  a = a || { title: '', author: 'فريق دليل السعودية', date: new Date().toISOString(), summary: '', body: '', images: [], cats: [], status: 'draft' };\n  const images = [...a.images];\n  const d = drawer(`<div class=\"row\"><div class=\"grow\"><h2>${isNew ? 'خبر جديد' : h(a.title)}</h2><div class=\"m muted\">${isNew ? 'بينحفظ مسودة' : `<span class=\"badge ${ST[a.status][1]}\">${ST[a.status][0]}</span>`}</div></div><button class=\"btn ghost\" id=\"x\">إغلاق</button></div>\n    <div class=\"f\"><label>العنوان *</label><input class=\"in\" id=\"title\" value=\"${h(a.title)}\"></div>\n    <div class=\"two\"><div class=\"f\"><label>الكاتب</label><input class=\"in\" id=\"author\" value=\"${h(a.author)}\"></div><div class=\"f\"><label>التاريخ</label><input class=\"in\" type=\"datetime-local\" id=\"date\" value=\"${toLocal(a.date)}\"></div></div>\n    <div class=\"f\"><label>الصور</label><div id=\"imgs\"></div></div>\n    <div class=\"f\"><label>ملخص</label><input class=\"in\" id=\"summary\" value=\"${h(a.summary)}\" maxlength=\"400\"></div>\n    <div class=\"f\"><label>النص</label><textarea class=\"in\" id=\"body\" style=\"min-height:260px\">${h(plainBody(a.body))}</textarea><small>سطر فاضي بين الفقرات</small></div>\n    <div class=\"bar\"><button class=\"btn\" id=\"save\">حفظ</button>${a.status !== 'live' ? '<button class=\"btn g\" id=\"pub\">حفظ وانشر</button>' : '<button class=\"btn ghost\" id=\"unpub\">رجّعه مسودة</button>'}${!isNew && a.status !== 'hidden' ? '<button class=\"btn ghost\" id=\"hide\" style=\"color:var(--pinkDeep)\">إخفاء</button>' : ''}</div>`);\n  imagesWidget($('#imgs', d), images);\n  $('#x', d).onclick = closeDrawer;\n  const save = async (status) => {\n    try {\n      const body = { title: $('#title', d).value, author: $('#author', d).value, date: fromLocal($('#date', d).value), summary: $('#summary', d).value, body: $('#body', d).value, images };\n      const r = await api(isNew ? '/admin/articles' : '/admin/articles/' + a.id, { method: isNew ? 'POST' : 'PUT', body });\n      if (status) await api(`/admin/articles/${r.article.id}/status`, { method: 'POST', body: { status } });\n      toast(status === 'live' ? 'انحفظ وانتشر' : 'انحفظ'); closeDrawer(); VIEW === 'articles' ? articlesView() : render();\n    } catch (e) { toast(errMsg(e)); }\n  };\n  $('#save', d).onclick = () => save();\n  $('#pub', d) && ($('#pub', d).onclick = () => save('live'));\n  $('#unpub', d) && ($('#unpub', d).onclick = () => save('draft'));\n  $('#hide', d) && ($('#hide', d).onclick = async () => { if (!confirm('تخفي الخبر؟')) return; await api(`/admin/articles/${a.id}/status`, { method: 'POST', body: { status: 'hidden' } }); toast('انخفى'); closeDrawer(); articlesView(); });\n}\n\n/* ——— المجتمع ——— */\nlet CTAB = 'reported';\nasync function communityView() {\n  const m = $('#main');\n  m.innerHTML = `<div class=\"row\"><div class=\"grow\"><h1>المجتمع</h1><p class=\"sub\">راجع اللي حوّلته المراجعة الذكية لك، والبلاغات وكل المشاركات، وأدر تحدي الأسبوع.</p></div><div class=\"row\"><button class=\"btn\" id=\"chBtn\">تحدي الأسبوع</button><button class=\"btn o\" id=\"msgBtn\">رسالة للمستخدمين ←</button></div></div>\n    <div class=\"tabs\">${[['pending', 'تنتظر مراجعتك' + (SUMMARY?.counts?.communityPending ? ` (${SUMMARY.counts.communityPending})` : '')], ['reported', 'البلاغات'], ['rejected', 'رفضتها المراجعة'], ['all', 'كل المشاركات']].map(([k, t]) => `<button data-c=\"${k}\" class=\"${CTAB === k ? 'on' : ''}\">${t}</button>`).join('')}</div><div id=\"res\" class=\"list\"><p class=\"muted\">لحظة...</p></div>`;\n  m.querySelectorAll('[data-c]').forEach((b) => (b.onclick = () => { CTAB = b.dataset.c; communityView(); }));\n  $('#msgBtn').onclick = () => { VIEW = 'messages'; render(); };\n  $('#chBtn').onclick = async () => {\n    const cur = (await api('/admin/challenge')).challenge || {};\n    const imgs = cur.photo ? [cur.photo] : [];\n    const d = drawer(`<div class=\"row\"><h2 class=\"grow\">تحدي الأسبوع</h2><button class=\"btn ghost\" id=\"x\">إغلاق</button></div>\n      <p class=\"muted\">يطلع بطاقة برتقالية فوق المجتمع. اللي يشارك يضغطها ويكتب مشاركته، وتنحسب المشاركات اللي فيها الوسم.</p>\n      <div class=\"f\"><label>عنوان التحدي</label><input class=\"in\" id=\"title\" value=\"${h(cur.title || '')}\" placeholder=\"صوّر غروب كورنيش جدة\"></div>\n      <div class=\"f\"><label>الجائزة</label><input class=\"in\" id=\"prize\" value=\"${h(cur.prize || '')}\" placeholder=\"وسم «عدسة الدليل» + كوبون\"></div>\n      <div class=\"two\"><div class=\"f\"><label>الوسم (بدون #)</label><input class=\"in\" id=\"tag\" value=\"${h(cur.tag || '')}\" placeholder=\"غروب_جدة\"></div><div class=\"f\"><label>ينتهي</label><input class=\"in\" type=\"datetime-local\" id=\"end\" value=\"${toLocal(cur.end)}\"></div></div>\n      <div class=\"f\"><label>صورة البطاقة</label><div id=\"imgs\"></div></div>\n      <div class=\"bar\"><button class=\"btn g\" id=\"save\">حفظ وانشر</button>${cur.title ? '<button class=\"btn ghost\" id=\"stop\" style=\"color:var(--pinkDeep)\">أوقف التحدي</button>' : ''}</div>`);\n    imagesWidget($('#imgs', d), imgs);\n    $('#x', d).onclick = closeDrawer;\n    $('#save', d).onclick = async () => { await api('/admin/challenge', { method: 'POST', body: { title: $('#title', d).value, prize: $('#prize', d).value, tag: $('#tag', d).value.replace(/^#/, ''), end: fromLocal($('#end', d).value), photo: imgs[0] || '' } }); toast('انحفظ التحدي'); closeDrawer(); };\n    $('#stop', d) && ($('#stop', d).onclick = async () => { await api('/admin/challenge', { method: 'POST', body: { clear: true } }); toast('وقف التحدي'); closeDrawer(); });\n  };\n  const why = { reports: 'انخفت بالبلاغات', owner: 'صاحبها حذفها', admin: 'أنت أخفيتها', account: 'الحساب انحذف' };\n  if (CTAB === 'pending' || CTAB === 'rejected') {\n    const d = await api('/admin/community/pending?status=' + CTAB);\n    const BY = { filter: 'الفلتر التلقائي', ai: 'المراجعة الذكية', admin_no: 'أنت رفضتها' };\n    const list = [...d.posts.map((x) => ({ ...x, t: 'p' })), ...d.answers.map((x) => ({ ...x, t: 'a' }))].sort((a, b) => b.created - a.created);\n    $('#res').innerHTML = list.map((x) => `<div class=\"post\"><div class=\"row\"><span class=\"tag\">${x.t === 'p' ? 'مشاركة' : 'إجابة'} #${x.id}</span><b style=\"font-size:13px\">${h(x.name || '')}</b><span class=\"muted\" style=\"font-size:13px\">${dAr(x.created)}${x.mod ? ' · ' + (BY[x.mod] || x.mod) : ''}</span></div>\n      ${x.question ? `<div class=\"muted\" style=\"font-size:13px\">على سؤال: ${h(x.question.slice(0, 140))}</div>` : ''}${x.photo ? `<img src=\"${h(x.photo)}\" style=\"max-width:260px;border-radius:14px\">` : ''}<div>${h(x.text)}</div>\n      ${x.mod_reason ? `<div class=\"muted\" style=\"font-size:13px\">السبب: ${h(x.mod_reason)}</div>` : ''}\n      <div class=\"row\"><button class=\"btn g\" data-rv=\"approve\" data-t=\"${x.t}\" data-id=\"${x.id}\">اعتمد وانشر</button>${CTAB === 'pending' ? `<button class=\"btn p\" data-rv=\"reject\" data-t=\"${x.t}\" data-id=\"${x.id}\">ارفض</button>` : ''}</div></div>`).join('') || `<div class=\"empty\">${CTAB === 'pending' ? 'ما فيه شي ينتظر مراجعتك' : 'ما فيه مشاركات مرفوضة'}</div>`;\n    m.querySelectorAll('[data-rv]').forEach((b) => (b.onclick = async () => {\n      const note = b.dataset.rv === 'reject' ? (prompt('سبب الرفض يوصل للمستخدم (اختياري)') || '') : '';\n      await api('/admin/community/review', { method: 'POST', body: { target: b.dataset.t, id: +b.dataset.id, decision: b.dataset.rv, note } });\n      toast(b.dataset.rv === 'approve' ? 'انتشرت' : 'انرفضت'); SUMMARY = null; communityView();\n    }));\n    return;\n  }\n  let rows;\n  if (CTAB === 'reported') {\n    const d = await api('/admin/community/reported');\n    rows = [...d.posts.map((x) => ({ ...x, t: 'p' })), ...d.answers.map((x) => ({ ...x, t: 'a' }))];\n  } else {\n    rows = (await api('/admin/community/posts')).posts.map((x) => ({ ...x, t: 'p' }));\n  }\n  const KN = { question: 'سؤال', tip: 'نصيحة', photo: 'صورة' };\n  $('#res').innerHTML = rows.map((x) => `<div class=\"post\"><div class=\"row\"><span class=\"tag\">${x.t === 'p' ? (KN[x.kind] || 'مشاركة') : 'إجابة'} #${x.id}</span>${x.name ? `<b style=\"font-size:13px\">${h(x.name)}</b>` : ''}<span class=\"badge ${x.status === 'visible' ? 'b-live' : 'b-hidden'}\">${x.status === 'visible' ? 'ظاهرة' : 'مخفية'}</span><span class=\"muted\" style=\"font-size:13px\">${x.reports ? x.reports + ' بلاغ' : ''}${x.hidden_by ? ' · ' + (why[x.hidden_by] || '') : ''}${x.answers != null ? ` · ${x.answers} إجابة · ${x.thanks} شكر` : ''}</span></div>\n    ${x.photo ? `<img src=\"${h(x.photo)}\" style=\"max-width:260px;border-radius:14px\">` : ''}<div>${h(x.text)}</div><div class=\"row\">${x.status === 'visible' ? `<button class=\"btn p\" data-t=\"${x.t}\" data-id=\"${x.id}\" data-h=\"1\">إخفاء</button>` : `<button class=\"btn g\" data-t=\"${x.t}\" data-id=\"${x.id}\" data-h=\"0\">أظهرها</button>`}</div></div>`).join('') || `<div class=\"empty\">${CTAB === 'reported' ? 'ما فيه بلاغات. المجتمع نظيف' : 'ما فيه مشاركات للحين'}</div>`;\n  m.querySelectorAll('[data-t]').forEach((b) => (b.onclick = async () => { await api('/admin/community/moderate', { method: 'POST', body: { target: b.dataset.t, id: +b.dataset.id, hidden: b.dataset.h === '1' } }); toast('تم'); communityView(); }));\n}\n\n/* ——— المستخدمين ——— */\nlet UTAB = 'all';\nasync function usersView(q = '') {\n  const m = $('#main');\n  if (!$('#uq') || m.dataset.ut !== UTAB) {\n    m.dataset.ut = UTAB;\n    m.innerHTML = `<h1>المستخدمين</h1><p class=\"sub\">«مرشد موثّق» يطلع جنب اسمه في المجتمع. «فريق الدليل» للإدارة. اللي يوصل 500 نقطة يقدر يطلب التوثيق من التطبيق.</p>\n      <div class=\"tabs\">${[['all', 'كل المستخدمين'], ['guides', 'طلبات «مرشد موثّق»']].map(([k, t]) => `<button data-u=\"${k}\" class=\"${UTAB === k ? 'on' : ''}\">${t}${k === 'guides' && SUMMARY?.counts?.guidesPending ? ` (${SUMMARY.counts.guidesPending})` : ''}</button>`).join('')}</div>\n      ${UTAB === 'all' ? '<div class=\"filters\"><input class=\"in\" id=\"uq\" placeholder=\"ابحث بالاسم\"></div>' : '<span id=\"uq\"></span>'}<div id=\"res\" class=\"list\"></div>`;\n    m.querySelectorAll('[data-u]').forEach((b) => (b.onclick = () => { UTAB = b.dataset.u; usersView(); }));\n  }\n  if (UTAB === 'guides') {\n    const d = await api('/admin/guides');\n    const GS = { pending: ['ينتظر', 'b-draft'], approved: ['انقبل', 'b-live'], rejected: ['مرفوض', 'b-hidden'] };\n    $('#res').innerHTML = d.requests.map((g) => `<div class=\"post\"><div class=\"row\"><b class=\"grow\">${h(g.name || 'بدون اسم')}</b><span class=\"muted\" style=\"font-size:13px\">${cityName(g.city)} · ${g.points} نقطة · ${g.answers} إجابة · ${g.best} أفضل إجابة · ${g.visits} زيارة</span><span class=\"badge ${GS[g.status][1]}\">${GS[g.status][0]}</span></div>\n      <div>${h(g.about || '')}</div>${g.note ? `<div class=\"muted\" style=\"font-size:13px\">ملاحظتك: ${h(g.note)}</div>` : ''}\n      ${g.status === 'pending' ? `<div class=\"row\"><button class=\"btn g\" data-g=\"${h(g.user_id)}\" data-s=\"approved\">اعتمده مرشد موثّق</button><button class=\"btn p\" data-g=\"${h(g.user_id)}\" data-s=\"rejected\">رفض</button></div>` : ''}</div>`).join('') || '<div class=\"empty\">ما فيه طلبات للحين</div>';\n    m.querySelectorAll('[data-g]').forEach((b) => (b.onclick = async () => {\n      let note = '';\n      if (b.dataset.s === 'rejected') { note = prompt('سبب الرفض (يوصله)؟'); if (note === null) return; }\n      await api('/admin/guides/' + encodeURIComponent(b.dataset.g), { method: 'POST', body: { status: b.dataset.s, note } }); toast('تم ووصله إشعار'); SUMMARY = null; usersView();\n    }));\n    return;\n  }\n  let t; $('#uq').oninput = (e) => { clearTimeout(t); t = setTimeout(() => usersView(e.target.value), 350); };\n  const d = await api('/admin/users' + (q ? '?q=' + encodeURIComponent(q) : ''));\n  const R = { user: 'مستخدم', guide: 'مرشد موثّق', admin: 'فريق الدليل' };\n  $('#res').innerHTML = d.users.map((u) => `<div class=\"item\" style=\"cursor:default\"><div class=\"ph\" style=\"border-radius:50%;background:var(--lilac);color:#fff;font-weight:700;font-size:20px\">${h((u.name || 'د')[0])}</div>\n    <div class=\"grow\"><div class=\"t\">${h(u.name || 'بدون اسم')}</div><div class=\"m\">${u.points} نقطة · ${cityName(u.city)} · سجّل ${new Date(u.created * 1000).toLocaleDateString('ar-SA-u-ca-gregory-nu-latn')}</div></div>\n    <select class=\"in\" style=\"width:auto\" data-r=\"${u.id}\">${Object.entries(R).map(([k, v]) => `<option value=\"${k}\" ${u.role === k ? 'selected' : ''}>${v}</option>`).join('')}</select></div>`).join('') || '<div class=\"empty\">ما فيه مستخدمين</div>';\n  m.querySelectorAll('select[data-r]').forEach((s) => (s.onchange = async () => { await api('/admin/community/role', { method: 'POST', body: { userId: s.dataset.r, role: s.value } }); toast('تغيّرت الصلاحية'); }));\n}\n\n/* ——— التجار والكوبونات ——— */\nlet MTAB = 'pending';\nconst MK = { restaurant: 'مطعم', cafe: 'مقهى', sweets: 'مخبز وحلويات', juice: 'عصيرات ومشروبات', dates: 'تمور ومنتجات محلية', perfume: 'عطور وبخور', gifts: 'هدايا وتذكارات', clothing: 'ملابس وعبايات', shop: 'متجر', mall: 'مول ومركز تسوق', hotel: 'فندق وشقق فندقية', resort: 'منتجع واستراحة', experience: 'تجربة سياحية', tours: 'جولات ومنظم رحلات', fun: 'ترفيه وألعاب', car: 'تأجير سيارات ونقل', umrah: 'خدمات الحج والعمرة', salon: 'صالون ومشغل', other: 'نشاط آخر' };\nconst MST = { pending: ['قيد المراجعة', 'b-draft'], approved: ['معتمد', 'b-live'], rejected: ['مرفوض', 'b-hidden'], hidden: ['موقوف', 'b-hidden'], active: ['فعّال', 'b-live'], paused: ['موقوف مؤقتاً', 'b-hidden'] };\nconst stB = (s) => `<span class=\"badge ${(MST[s] || ['', 'b-hidden'])[1]}\">${(MST[s] || [s])[0]}</span>`;\nconst dAr = (t) => new Date(t * 1000).toLocaleDateString('ar-SA-u-ca-gregory-nu-latn', { timeZone: 'Asia/Riyadh', day: 'numeric', month: 'short' });\nasync function merchantsView() {\n  const m = $('#main');\n  m.innerHTML = `<h1>التجار والكوبونات</h1><p class=\"sub\">أصحاب المحلات يسجّلون من التطبيق (الملف الشخصي ← «سجّل نشاطك»). ما يظهر شي للزوار لين توافق هنا.</p>\n    <div class=\"tabs\">${[['pending', 'طلبات جديدة'], ['coupons', 'كوبونات تنتظر'], ['reports', `بلاغات العملاء${SUMMARY?.counts?.creportsPending ? ' (' + SUMMARY.counts.creportsPending + ')' : ''}`], ['approved', 'التجار المعتمدين'], ['allc', 'كل الكوبونات'], ['rejected', 'مرفوض / موقوف']].map(([k, t]) => `<button data-m=\"${k}\" class=\"${MTAB === k ? 'on' : ''}\">${t}</button>`).join('')}</div><div id=\"res\" class=\"list\"><p class=\"muted\">لحظة...</p></div>`;\n  m.querySelectorAll('[data-m]').forEach((b) => (b.onclick = () => { MTAB = b.dataset.m; merchantsView(); }));\n  if (MTAB === 'reports') {\n    const RS = { refused: 'المحل رفض الكوبون', different: 'العرض مختلف عن المكتوب', conditions: 'شروط ما كانت مكتوبة', closed: 'المحل مقفل', other: 'مشكلة ثانية' };\n    const d = await api('/admin/coupon-reports');\n    $('#res').innerHTML = `<div class=\"hint\" style=\"margin-bottom:10px\">3 بلاغات من 3 أشخاص على نفس الكوبون توقفه تلقائياً. «ثبت البلاغ» يعطي العميل 20 نقطة اعتذار ويسجل مخالفة على التاجر، و3 مخالفات توقف النشاط كامل.</div>` + (d.reports.map((r) => `<div class=\"post\"><div class=\"row\"><span class=\"badge b-draft\">${RS[r.reason] || r.reason}</span><b class=\"grow\">${h(r.coupon.title)}</b><span class=\"muted\" style=\"font-size:13px\">${h(r.merchant.name)} · ${cityName(r.merchant.city)} · من ${h(r.user)} · ${dAr(r.created)}</span></div>\n      ${r.note ? `<div>«${h(r.note)}»</div>` : ''}<div class=\"muted\" style=\"font-size:13px\">على هالتاجر: ${r.merchant.reports} بلاغ · ${r.merchant.strikes} مخالفة مؤكدة من 3 · الكوبون ${r.coupon.status === 'paused' ? 'موقوف تلقائياً' : (MST[r.coupon.status] || [r.coupon.status])[0]}</div>\n      <div class=\"row\"><button class=\"btn p\" data-rp=\"${r.id}\" data-s=\"confirmed\">ثبت البلاغ</button><button class=\"btn ghost\" data-rp=\"${r.id}\" data-s=\"dismissed\">ما ثبت</button></div></div>`).join('') || '<div class=\"empty\">ما فيه بلاغات. التجار ملتزمين</div>');\n    m.querySelectorAll('[data-rp]').forEach((b) => (b.onclick = async () => {\n      if (b.dataset.s === 'confirmed' && !confirm('تثبت البلاغ؟ العميل ياخذ 20 نقطة والتاجر تنسجل عليه مخالفة.')) return;\n      await api('/admin/coupon-reports/' + b.dataset.rp, { method: 'POST', body: { status: b.dataset.s } }); toast('تم ووصلهم إشعار'); SUMMARY = null; merchantsView();\n    }));\n    return;\n  }\n  if (MTAB === 'coupons' || MTAB === 'allc') {\n    const d = await api('/admin/coupons?status=' + (MTAB === 'coupons' ? 'pending' : 'all'));\n    $('#res').innerHTML = d.coupons.map((c) => `<div class=\"post\"><div class=\"row\"><span style=\"background:var(--orange);color:#fff;border-radius:14px;padding:8px 12px;font-weight:700\">${h(c.off)}</span>\n      <div class=\"grow\"><div class=\"t\" style=\"font-weight:700\">${h(c.title)}</div><div class=\"m muted\" style=\"font-size:13px\">${h(c.merchant.name)} · ${cityName(c.merchant.city)} ${c.merchant.status !== 'approved' ? '· <b style=\"color:var(--orangeDeep)\">النشاط نفسه ما انعتمد للحين</b>' : ''}</div></div>${stB(c.status)}</div>\n      <div class=\"muted\" style=\"font-size:13px\">${[c.minOrder ? `الحد الأدنى ${c.minOrder} ر.س` : '', c.perUser ? 'مرة وحدة لكل مستخدم' : 'أكثر من مرة', c.qty ? `العدد ${c.qty}` : 'بدون حد', c.hours, c.license ? `ترخيص التخفيضات: ${c.license}` : 'بدون رقم ترخيص', c.points ? `يتبادل بـ ${c.points} نقطة` : '', c.minLevel ? `حصري لمستوى ${c.minLevel}+ (${c.levelName})` : '', c.start ? 'من ' + c.start : '', c.end ? 'إلى ' + c.end : '', `استُخدم ${c.used} · شوهد ${c.views}`].filter(Boolean).join(' · ')}</div>\n      ${c.terms ? `<div style=\"font-size:14px\">${h(c.terms)}</div>` : ''}\n      <div class=\"row\">${c.status !== 'active' ? `<button class=\"btn g\" data-c=\"${c.id}\" data-s=\"active\">اعتمد وانشر</button>` : `<button class=\"btn ghost\" data-c=\"${c.id}\" data-s=\"paused\">أوقف مؤقتاً</button>`}${c.status === 'pending' ? `<button class=\"btn p\" data-c=\"${c.id}\" data-s=\"rejected\" data-why=\"1\">يحتاج تعديل</button>` : ''}${c.status !== 'hidden' ? `<button class=\"btn ghost\" data-c=\"${c.id}\" data-s=\"hidden\">إخفاء</button>` : ''}</div></div>`).join('') || `<div class=\"empty\">${MTAB === 'coupons' ? 'ما فيه كوبونات تنتظر' : 'ما فيه كوبونات'}</div>`;\n    m.querySelectorAll('[data-c]').forEach((b) => (b.onclick = async () => {\n      let note;\n      if (b.dataset.why) { note = prompt('وش يحتاج يتعدّل؟ (توصل للتاجر)'); if (note === null) return; }\n      await api('/admin/coupons/' + b.dataset.c, { method: 'POST', body: { status: b.dataset.s, note } }); toast('تم'); SUMMARY = null; merchantsView();\n    }));\n    return;\n  }\n  const st = MTAB === 'rejected' ? 'all' : MTAB;\n  let list = (await api('/admin/merchants?status=' + st)).merchants;\n  if (MTAB === 'rejected') list = list.filter((x) => x.status === 'rejected' || x.status === 'hidden');\n  $('#res').innerHTML = list.map((x) => `<div class=\"item\" data-id=\"${x.id}\">${x.photos[0] ? `<img src=\"${h(x.photos[0])}\">` : '<div class=\"ph\">بدون صورة</div>'}\n    <div class=\"grow\"><div class=\"t\">${h(x.name)} ${x.verified ? '<span class=\"badge b-live\">موثّق</span>' : ''}</div><div class=\"m\">${MK[x.kind] || x.kind} · ${cityName(x.city)}${x.area ? ' · ' + h(x.area) : ''} · ${h(x.owner || 'بدون اسم')} · ${dAr(x.updated)}</div>\n    <div class=\"m\">${x.coupons} كوبون · ${x.used} استخدام${x.placeTitle ? ' · مربوط بـ«' + h(x.placeTitle) + '»' : ''}</div></div>${stB(x.status)}</div>`).join('') || `<div class=\"empty\">${MTAB === 'pending' ? 'ما فيه طلبات جديدة' : 'ما فيه أحد هنا'}</div>`;\n  m.querySelectorAll('.item[data-id]').forEach((el) => (el.onclick = () => editMerchant(list.find((x) => x.id === +el.dataset.id))));\n}\nfunction editMerchant(x) {\n  const d = drawer(`<div class=\"row\"><h2 class=\"grow\">${h(x.name)}</h2>${stB(x.status)}<button class=\"btn ghost\" id=\"x\">إغلاق</button></div>\n    <p class=\"muted\">${MK[x.kind] || ''} · ${cityName(x.city)}${x.area ? ' · ' + h(x.area) : ''}${x.name_en ? ' · ' + h(x.name_en) : ''}</p>\n    ${x.photos.length ? `<div class=\"imgs\">${x.photos.map((u) => `<a class=\"im\" href=\"${h(u)}\" target=\"_blank\"><img src=\"${h(u)}\"></a>`).join('')}</div>` : '<div class=\"warn\">ما رفع صور</div>'}\n    <div class=\"two\"><div class=\"f\"><label>صاحب الحساب</label><div>${h(x.owner || '—')}${x.ownerEmail ? '<br><small>' + h(x.ownerEmail) + '</small>' : ''}</div></div><div class=\"f\"><label>الجوال</label><div>${h(x.phone || '—')}</div></div></div>\n    <div class=\"two\"><div class=\"f\"><label>ساعات العمل</label><div>${h(x.hours || '—')}</div></div><div class=\"f\"><label>السجل التجاري / معروف</label><div>${h(x.cr || '—')}</div><small>تحقق منه قبل «موثّق»</small></div></div>\n    <div class=\"${x.termsOk ? 'hint' : 'warn'}\" style=\"margin-top:12px\">${x.termsVersion ? `وافق على الشروط والأحكام (نسخة ${h(x.termsVersion)}) بتاريخ ${x.termsAt ? new Date(x.termsAt * 1000).toLocaleString('ar-SA-u-ca-gregory-nu-latn', { timeZone: 'Asia/Riyadh' }) : '—'}${x.agreeIp ? ' · الجهاز ' + h(x.agreeIp) : ''}${x.termsOk ? '' : ' · <b>يحتاج يوافق على النسخة الجديدة</b>'}` : 'ما وافق على الشروط والأحكام للحين'}</div>\n    <div class=\"f\"><label><input type=\"checkbox\" id=\"ver\" ${x.verified ? 'checked' : ''}> موثّق (تطلع علامة «موثّق» جنب الاسم)</label></div>\n    <div class=\"two\"><div class=\"f\"><label>عدد الكوبونات الفعّالة المسموحة</label><input class=\"in\" id=\"max\" type=\"number\" min=\"0\" max=\"20\" value=\"${x.maxCoupons}\"><small>الباقة المجانية = 1</small></div>\n    <div class=\"f\"><label>ربطه بمكان في الدليل</label><input class=\"in\" id=\"pq\" placeholder=\"ابحث باسم المكان\" value=\"${h(x.placeTitle)}\"><input type=\"hidden\" id=\"pid\" value=\"${x.placeId || ''}\"><div id=\"psug\" class=\"list\" style=\"margin-top:6px\"></div><small>الكوبون يطلع في صفحة هذا المكان</small></div></div>\n    <div class=\"f\"><label>الموقع على الخريطة</label><div id=\"geoBox\"></div></div>\n    <div class=\"f\"><label>ملاحظة للتاجر (تنرسل مع الرفض)</label><input class=\"in\" id=\"note\" value=\"${h(x.note)}\" placeholder=\"مثلاً: الصور مو واضحة، ارفع صورة للواجهة\"></div>\n    <div class=\"bar\"><button class=\"btn g\" data-s=\"approved\">${x.status === 'approved' ? 'حفظ' : 'اعتمد'}</button>${x.status === 'pending' ? '<button class=\"btn p\" data-s=\"rejected\">رفض</button>' : ''}${x.status === 'approved' ? '<button class=\"btn ghost\" data-s=\"hidden\" style=\"color:var(--pinkDeep)\">إيقاف النشاط</button>' : ''}${x.status !== 'pending' && x.status !== 'approved' ? '<button class=\"btn ghost\" data-s=\"pending\">رجّعه للمراجعة</button>' : ''}</div>`);\n  $('#x', d).onclick = closeDrawer;\n  let geo = { lat: x.lat, lng: x.lng };\n  geoWidget($('#geoBox', d), x.lat, x.lng, () => x.city, null, (la, ln) => { geo = { lat: la, lng: ln }; });\n  let t; $('#pq', d).oninput = (e) => {\n    clearTimeout(t); const v = e.target.value.trim(); if (!v) { $('#pid', d).value = ''; $('#psug', d).innerHTML = ''; return; }\n    t = setTimeout(async () => {\n      const r = await api(`/admin/places?q=${encodeURIComponent(v)}&city=${x.city}&per=6`);\n      $('#psug', d).innerHTML = r.places.map((p) => `<div class=\"chip\" data-p=\"${p.id}\" data-t=\"${h(p.title)}\">${h(p.title)}</div>`).join('') || '<small class=\"muted\">ما لقينا</small>';\n      $('#psug', d).querySelectorAll('[data-p]').forEach((c) => (c.onclick = () => { $('#pid', d).value = c.dataset.p; $('#pq', d).value = c.dataset.t; $('#psug', d).innerHTML = ''; }));\n    }, 300);\n  };\n  d.querySelectorAll('.bar [data-s]').forEach((b) => (b.onclick = async () => {\n    const s = b.dataset.s;\n    if (s === 'rejected' && !$('#note', d).value.trim() && !confirm('ترفض بدون ملاحظة؟')) return;\n    if (s === 'hidden' && !confirm('توقف النشاط؟ كوبوناته تختفي من التطبيق.')) return;\n    try {\n      await api('/admin/merchants/' + x.id, { method: 'POST', body: { status: s, verified: $('#ver', d).checked, maxCoupons: +$('#max', d).value, placeId: $('#pid', d).value || null, note: $('#note', d).value, lat: geo.lat, lng: geo.lng } });\n      toast(s === 'approved' ? 'انعتمد ووصله إشعار' : s === 'rejected' ? 'انرفض ووصلته الملاحظة' : 'تم'); closeDrawer(); SUMMARY = null; merchantsView();\n    } catch (e) { toast(errMsg(e)); }\n  }));\n}\n\n/* ——— صور الزوار والتقييمات ——— */\nlet PTAB = 'pending';\nasync function photosView() {\n  const m = $('#main');\n  m.innerHTML = `<h1>صور الزوار والتقييمات</h1><p class=\"sub\">الصور ما تنزل في صفحة المكان لين توافق عليها. كل صورة تنقبل تعطي صاحبها 5 نقاط.</p>\n    <div class=\"tabs\">${[['pending', 'صور تنتظر'], ['approved', 'صور منشورة'], ['rejected', 'صور مرفوضة'], ['reviews', 'آخر التقييمات'], ['reported', 'تقييمات عليها بلاغ']].map(([k, t]) => `<button data-p=\"${k}\" class=\"${PTAB === k ? 'on' : ''}\">${t}</button>`).join('')}</div><div id=\"tools\"></div><div id=\"res\"><p class=\"muted\">لحظة...</p></div>`;\n  m.querySelectorAll('[data-p]').forEach((b) => (b.onclick = () => { PTAB = b.dataset.p; photosView(); }));\n  if (PTAB === 'reviews' || PTAB === 'reported') {\n    const d = await api('/admin/reviews' + (PTAB === 'reported' ? '?status=reported' : ''));\n    $('#res').innerHTML = `<div class=\"list\">${d.reviews.map((r) => `<div class=\"post\"><div class=\"row\"><b style=\"color:var(--orangeDeep)\">${'★'.repeat(r.stars)}${'☆'.repeat(5 - r.stars)}</b><b>${h(r.place.title)}</b><span class=\"muted\" style=\"font-size:13px\">${cityName(r.place.city)} · ${h(r.user.name)} · ${dAr(r.updated)}${r.reports ? ' · ' + r.reports + ' بلاغ' : ''}</span><span class=\"badge ${r.status === 'visible' ? 'b-live' : 'b-hidden'}\">${r.status === 'visible' ? 'ظاهر' : 'مخفي'}</span></div>\n      ${r.tags.length ? `<div class=\"chips\">${r.tags.map((t) => `<span class=\"chip\">${h(t)}</span>`).join('')}</div>` : ''}${r.text ? `<div>${h(r.text)}</div>` : ''}\n      <div class=\"row\">${r.status === 'visible' ? `<button class=\"btn p\" data-r=\"${r.id}\" data-s=\"hidden\">إخفاء</button>` : `<button class=\"btn g\" data-r=\"${r.id}\" data-s=\"visible\">أظهره</button>`}</div></div>`).join('') || '<div class=\"empty\">ما فيه شي هنا</div>'}</div>`;\n    m.querySelectorAll('[data-r]').forEach((b) => (b.onclick = async () => { await api('/admin/reviews/' + b.dataset.r, { method: 'POST', body: { status: b.dataset.s } }); toast('تم'); photosView(); }));\n    return;\n  }\n  const d = await api('/admin/photos?status=' + PTAB);\n  const sel = new Set();\n  if (PTAB === 'pending' && d.photos.length) $('#tools').innerHTML = `<div class=\"row\" style=\"margin-bottom:12px\"><button class=\"btn ghost\" id=\"all\">تحديد الكل</button><button class=\"btn g\" id=\"okAll\" disabled>اقبل المحدد</button><button class=\"btn p\" id=\"noAll\" disabled>ارفض المحدد</button><span class=\"muted\" id=\"cnt\"></span></div>`;\n  $('#res').innerHTML = `<div style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px\">${d.photos.map((x) => `<div class=\"card\" style=\"padding:8px\" data-ph=\"${x.id}\">\n    <a href=\"${h(x.url)}\" target=\"_blank\"><img src=\"${h(x.url)}\" style=\"width:100%;height:170px;object-fit:cover;border-radius:14px;display:block\"></a>\n    <div style=\"padding:6px 4px\"><div style=\"font-weight:700;font-size:14px\">${h(x.place.title)}</div><div class=\"muted\" style=\"font-size:12px\">${cityName(x.place.city)} · ${h(x.user.name)} · ${dAr(x.created)}${x.reports ? ` · <b style=\"color:var(--pinkDeep)\">${x.reports} بلاغ</b>` : ''}</div>\n    ${x.review ? `<div style=\"font-size:12px;margin-top:4px\"><b style=\"color:var(--orangeDeep)\">${'★'.repeat(x.review.stars)}</b> ${h((x.review.text || '').slice(0, 80))}</div>` : ''}</div>\n    <div class=\"row\">${PTAB === 'pending' ? `<label style=\"font-size:13px\"><input type=\"checkbox\" data-sel=\"${x.id}\"> تحديد</label><span class=\"grow\"></span>` : ''}${x.status !== 'approved' ? `<button class=\"mini\" style=\"background:var(--softGreen);color:var(--green)\" data-a=\"${x.id}\" data-s=\"approved\">اقبل</button>` : ''}${x.status !== 'rejected' ? `<button class=\"mini\" style=\"background:var(--softPink);color:var(--pinkDeep)\" data-a=\"${x.id}\" data-s=\"rejected\">${x.status === 'approved' ? 'شيلها' : 'ارفض'}</button>` : ''}</div></div>`).join('')}</div>${d.photos.length ? '' : `<div class=\"empty\">${PTAB === 'pending' ? 'ما فيه صور تنتظر' : 'ما فيه صور'}</div>`}`;\n  const upd = () => { $('#cnt') && ($('#cnt').textContent = sel.size ? sel.size + ' محددة' : ''); $('#okAll') && ($('#okAll').disabled = $('#noAll').disabled = !sel.size); };\n  m.querySelectorAll('[data-sel]').forEach((c) => (c.onchange = () => { c.checked ? sel.add(+c.dataset.sel) : sel.delete(+c.dataset.sel); upd(); }));\n  $('#all') && ($('#all').onclick = () => { m.querySelectorAll('[data-sel]').forEach((c) => { c.checked = true; sel.add(+c.dataset.sel); }); upd(); });\n  const bulk = async (s) => { await api('/admin/photos/bulk', { method: 'POST', body: { ids: [...sel], status: s } }); toast(s === 'approved' ? 'انقبلت' : 'انرفضت'); SUMMARY = null; photosView(); };\n  $('#okAll') && ($('#okAll').onclick = () => bulk('approved'));\n  $('#noAll') && ($('#noAll').onclick = () => confirm('ترفض الصور المحددة؟') && bulk('rejected'));\n  m.querySelectorAll('[data-a]').forEach((b) => (b.onclick = async () => { await api('/admin/photos/' + b.dataset.a, { method: 'POST', body: { status: b.dataset.s } }); toast('تم'); SUMMARY = null; photosView(); }));\n}\n\n/* ——— الرسائل والإشعارات ——— */\nconst SEG = [['all', 'الكل'], ['new', 'الجدد (آخر 7 أيام)'], ['inactive', 'غايبين +30 يوم'], ['guides', 'المرشدين وفريق الدليل'], ['merchants', 'التجار المعتمدين']];\nconst LINKS = [['', 'الإشعارات (بدون رابط)'], ['/', 'الرئيسية'], ['/explore', 'الدليل'], ['/events', 'الفعاليات'], ['/community', 'المجتمع'], ['/coupons', 'الكوبونات'], ['/trip', 'رحلتي'], ['custom', 'مكان أو فعالية معينة...']];\nasync function messagesView() {\n  const m = $('#main');\n  m.innerHTML = '<p class=\"muted\">لحظة...</p>';\n  const d = await api('/admin/messages');\n  const cities = new Set();\n  m.innerHTML = `<h1>الرسائل والإشعارات</h1><p class=\"sub\">الرسالة تنزل في «الإشعارات» داخل التطبيق، وتوصل إشعار على شاشة الجوال للأجهزة اللي فعّلت الإشعارات.</p>\n  <div style=\"display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:14px\" class=\"msgGrid\">\n   <div class=\"card\"><b style=\"font-size:17px\">رسالة جديدة</b>\n    <div class=\"f\"><label>العنوان (اختياري)</label><input class=\"in\" id=\"mt\" maxlength=\"60\" placeholder=\"ويكند العلا يناديك\"></div>\n    <div class=\"f\"><label>النص</label><textarea class=\"in\" id=\"mx\" maxlength=\"178\" style=\"min-height:80px\" placeholder=\"الجو 24° والنجوم واضحة. شوف مختارات الأسبوع وخطط رحلتك.\"></textarea><small id=\"mxn\">0 / 178</small></div>\n    <div class=\"two\"><div class=\"f\"><label>يفتح على</label><select class=\"in\" id=\"ml\">${LINKS.map(([v, t]) => `<option value=\"${v}\">${t}</option>`).join('')}</select><input class=\"in\" id=\"mlc\" placeholder=\"/place/123 أو /event/900000001\" style=\"display:none;margin-top:6px\"></div>\n    <div class=\"f\"><label>مين يوصله</label><select class=\"in\" id=\"ms\">${SEG.map(([v, t]) => `<option value=\"${v}\">${t}</option>`).join('')}</select></div></div>\n    <div class=\"f\"><label>المدن (فاضي = كل المدن)</label><div class=\"chips\" id=\"mc\">${META.cities.map((c) => `<span class=\"chip\" data-c=\"${c.id}\">${h(c.name)}</span>`).join('')}</div></div>\n    <div class=\"hint\" id=\"est\" style=\"margin-top:12px\">...</div>\n    <div class=\"two\"><div class=\"f\"><label>متى</label><select class=\"in\" id=\"mw\"><option value=\"now\">الحين</option><option value=\"later\">وقت معيّن</option></select><input class=\"in\" type=\"datetime-local\" id=\"mat\" style=\"display:none;margin-top:6px\"><small>بتوقيت مكة. المجدول يطلع خلال الساعة اللي حددتها</small></div>\n    <div class=\"f\"><label>القنوات</label><label><input type=\"checkbox\" id=\"cin\" checked> داخل التطبيق</label><label><input type=\"checkbox\" id=\"cpu\" checked> إشعار الجوال</label></div></div>\n    <div class=\"row\" style=\"margin-top:16px\"><button class=\"btn o\" id=\"send\">أرسل</button></div></div>\n   <div style=\"display:grid;gap:14px;align-content:start\">\n    <div class=\"card\" style=\"background:var(--ink);color:#fff\"><div style=\"font-size:13px;color:#CFC6DE\">معاينة على الجوال</div>\n     <div style=\"margin-top:12px;background:rgba(255,255,255,.12);border-radius:16px;padding:12px;display:flex;gap:10px\"><span style=\"width:36px;height:36px;border-radius:9px;background:var(--purple);display:grid;place-items:center;font-weight:700;flex:none\">د</span><div style=\"flex:1;min-width:0\"><div style=\"display:flex;justify-content:space-between;font-size:12px;color:#CFC6DE\"><span>دليل السعودية</span><span>الحين</span></div><div style=\"font-weight:700\" id=\"pt\">دليل السعودية</div><div style=\"font-size:13px;color:#E2DAEE\" id=\"px\">نص الرسالة يطلع هنا</div></div></div></div>\n    <div class=\"card\"><b>حماية المستخدم</b><div class=\"muted\" style=\"font-size:13px;line-height:1.9;margin-top:6px\">• ساعات هدوء 11 م – 8 ص: إشعار الجوال يتأجل لـ 8 الصبح، والرسالة داخل التطبيق تنزل على وقتها.<br>• الأجهزة المسجلة الحين: <b>${d.devices}</b>. إشعارات الجوال تشتغل فعلياً بعد النسخة الجاية من التطبيق (تحتاج مفتاح آبل للإشعارات).</div></div>\n   </div></div>\n  <h2 style=\"margin:24px 0 10px;font-size:19px\">السجل</h2>\n  <div class=\"list\">${d.messages.map((x) => `<div class=\"post\"><div class=\"row\"><b class=\"grow\">${h(x.title || x.text.slice(0, 50))}</b><span class=\"badge ${x.status === 'sent' ? 'b-live' : x.status === 'scheduled' ? 'b-draft' : 'b-hidden'}\">${x.status === 'sent' ? 'انرسلت' : x.status === 'scheduled' ? 'مجدولة' : 'ملغية'}</span></div>\n    <div class=\"muted\" style=\"font-size:13px\">${h(x.text)}</div>\n    <div class=\"muted\" style=\"font-size:12px\">${new Date(x.at * 1000).toLocaleString('ar-SA-u-ca-gregory-nu-latn', { timeZone: 'Asia/Riyadh', day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' })} · ${(SEG.find((s) => s[0] === x.audience.segment) || ['', 'الكل'])[1]}${x.audience.cities?.length ? ' · ' + x.audience.cities.map(cityName).join('، ') : ''}${x.status === 'sent' || x.sent_inapp ? ` · داخل التطبيق: ${Math.max(0, x.sent_inapp)} · الجوال: ${Math.max(0, x.sent_push)}${x.push_errors ? ` (تعذّر ${x.push_errors})` : ''}` : ''}${x.link ? ' · يفتح ' + h(x.link) : ''}</div>\n    ${x.status === 'scheduled' && !x.sent_inapp ? `<div><button class=\"mini\" style=\"background:var(--softPink);color:var(--pinkDeep)\" data-cancel=\"${x.id}\">ألغِ</button></div>` : ''}</div>`).join('') || '<div class=\"empty\">ما أرسلت رسائل للحين</div>'}</div>`;\n  const pv = () => { $('#pt').textContent = $('#mt').value || 'دليل السعودية'; $('#px').textContent = $('#mx').value || 'نص الرسالة يطلع هنا'; $('#mxn').textContent = $('#mx').value.length + ' / 178'; };\n  $('#mt').oninput = pv; $('#mx').oninput = pv;\n  $('#ml').onchange = () => { $('#mlc').style.display = $('#ml').value === 'custom' ? '' : 'none'; };\n  $('#mw').onchange = () => { $('#mat').style.display = $('#mw').value === 'later' ? '' : 'none'; };\n  const aud = () => ({ segment: $('#ms').value, cities: [...cities] });\n  let et; const est = () => { clearTimeout(et); et = setTimeout(async () => { try { const r = await api('/admin/messages/estimate', { method: 'POST', body: aud() }); $('#est').textContent = `توصل تقريباً لـ ${r.users} مستخدم داخل التطبيق، و ${r.devices} جهاز إشعار.`; } catch {} }, 250); };\n  $('#ms').onchange = est;\n  m.querySelectorAll('#mc [data-c]').forEach((c) => (c.onclick = () => { const id = c.dataset.c; cities.has(id) ? cities.delete(id) : cities.add(id); c.classList.toggle('on'); est(); }));\n  est();\n  $('#send').onclick = async () => {\n    const text = $('#mx').value.trim(); if (text.length < 4) return toast('اكتب نص الرسالة');\n    const link = $('#ml').value === 'custom' ? $('#mlc').value.trim() : $('#ml').value;\n    if ($('#ml').value === 'custom' && !/^\\/[a-z]+\\/\\d+$/i.test(link)) return toast('الرابط لازم مثل /place/123');\n    const later = $('#mw').value === 'later';\n    if (later && !$('#mat').value) return toast('حدد الوقت');\n    if (!confirm(later ? 'تجدول الرسالة؟' : 'ترسلها الحين؟ ما تقدر ترجعها بعد الإرسال.')) return;\n    try {\n      const r = await api('/admin/messages', { method: 'POST', body: { title: $('#mt').value, text, link, ...aud(), at: later ? fromLocal($('#mat').value) : '', inapp: $('#cin').checked, push: $('#cpu').checked } });\n      toast(r.sent ? `انرسلت: ${r.inapp} داخل التطبيق${r.pushDelayed ? '، وإشعار الجوال الساعة 8 الصبح' : r.push ? '، ' + r.push + ' جوال' : ''}` : 'انجدولت');\n      messagesView();\n    } catch (e) { toast(errMsg(e)); }\n  };\n  m.querySelectorAll('[data-cancel]').forEach((b) => (b.onclick = async () => { if (!confirm('تلغي الرسالة المجدولة؟')) return; await api(`/admin/messages/${b.dataset.cancel}/cancel`, { method: 'POST' }); toast('انلغت'); messagesView(); }));\n}\n\n/* ——— الأوسمة والنقاط ——— */\nasync function badgesView() {\n  const m = $('#main');\n  m.innerHTML = '<p class=\"muted\">لحظة...</p>';\n  const d = await api('/admin/badges');\n  const max = Math.max(1, ...d.levels.map((l) => l.users));\n  m.innerHTML = `<h1>الأوسمة والنقاط</h1><p class=\"sub\">النقاط تجي من المشاركة: سؤال +2، إجابة +5، أفضل إجابة +15، شكر +1، تقييم مكان +3، صورة مقبولة +5، زيارة مؤكدة +10 (ومدينة جديدة +25).</p>\n    <div class=\"stats\">${[[d.total, 'مستخدم', 'var(--purple)'], [d.guides, 'مرشد موثّق', 'var(--green)'], [d.badges.reduce((a, b) => a + (b.users || 0), 0), 'وسام محصّل', 'var(--orangeDeep)']].map(([n, l, c]) => `<div class=\"stat\"><div class=\"n\" style=\"color:${c}\">${n}</div><div class=\"l\">${l}</div></div>`).join('')}</div>\n    <div style=\"display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px\" class=\"msgGrid\">\n    <div class=\"card\"><b>الأوسمة</b><div class=\"list\" style=\"margin-top:10px\">${d.badges.map((b) => `<div class=\"row\" style=\"padding:8px 0;border-bottom:1px solid var(--chip)\"><span style=\"width:38px;height:38px;border-radius:12px;background:var(--softOrange);display:grid;place-items:center;color:var(--orangeDeep);font-weight:700\">★</span><div class=\"grow\"><b>${h(b.name)}</b><div class=\"muted\" style=\"font-size:12px\">${({ questions: 'سؤال', tips: 'نصيحة', answers: 'إجابة', best: 'أفضل إجابة', photos: 'صورة', thanks: 'شكر', trip: 'مكان في رحلتي', visits: 'زيارة مؤكدة', cities: 'مدينة مزارة', reviews: 'تقييم' })[b.key] || b.key} × ${b.goal}</div></div><b>${b.users == null ? '—' : b.users}</b><span class=\"muted\" style=\"font-size:12px\">مستخدم</span></div>`).join('')}</div></div>\n    <div class=\"card\"><b>المستويات</b><div style=\"margin-top:10px;display:grid;gap:8px\">${d.levels.map((l, i) => `<div><div class=\"row\" style=\"font-size:13px\"><b>${i + 1}. ${h(l.name)}</b><span class=\"muted\">من ${l.at} نقطة</span><span class=\"grow\"></span><b>${l.users}</b></div><div style=\"height:8px;background:var(--chip);border-radius:4px;margin-top:4px\"><div style=\"height:100%;width:${(l.users / max) * 100}%;background:var(--lilac);border-radius:4px\"></div></div></div>`).join('')}</div></div></div>\n    <div class=\"card\" style=\"margin-top:14px\" id=\"heroes\"></div>\n    <div class=\"card\" style=\"margin-top:14px\"><b>أعلى 25 مستخدم</b><div class=\"list\" style=\"margin-top:10px\">${d.top.map((u, i) => `<div class=\"row\" style=\"padding:6px 0;border-bottom:1px solid var(--chip)\"><b style=\"width:26px\">${i + 1}</b><div class=\"grow\"><b>${h(u.name || 'بدون اسم')}</b> ${u.role === 'guide' ? '<span class=\"badge b-live\">مرشد</span>' : u.role === 'admin' ? '<span class=\"badge b-panel\">فريق الدليل</span>' : ''}<div class=\"muted\" style=\"font-size:12px\">${cityName(u.city)} · ${u.answers} إجابة · ${u.visits} زيارة</div></div><b style=\"color:var(--orangeDeep)\">${u.points}</b></div>`).join('') || '<div class=\"muted\">ما فيه مستخدمين</div>'}</div><p class=\"muted\" style=\"font-size:13px\">تقدر تعطي أحد «مرشد موثّق» من صفحة المستخدمين.</p></div>`;\n  heroesBlock($('#heroes'));\n}\n\n/* ——— التحليلات ——— */\nfunction spark(arr, color) {\n  const W = 300, H = 70, mx = Math.max(1, ...arr), step = W / (arr.length - 1 || 1);\n  const pts = arr.map((v, i) => `${(i * step).toFixed(1)},${(H - 4 - (v / mx) * (H - 12)).toFixed(1)}`).join(' ');\n  return `<svg viewBox=\"0 0 ${W} ${H}\" style=\"width:100%;height:70px;display:block\" preserveAspectRatio=\"none\"><polyline points=\"0,${H} ${pts} ${W},${H}\" fill=\"${color}22\" stroke=\"none\"/><polyline points=\"${pts}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/></svg>`;\n}\nasync function analyticsView() {\n  const m = $('#main');\n  m.innerHTML = '<p class=\"muted\">لحظة...</p>';\n  const d = await api('/admin/analytics');\n  const c = d.counts, s = d.series, sum = (a) => a.reduce((x, y) => x + y, 0);\n  const first = new Date(d.day0 * 86400e3), last = new Date((d.day0 + 29) * 86400e3);\n  const dd = (x) => x.toLocaleDateString('ar-SA-u-ca-gregory-nu-latn', { day: 'numeric', month: 'short', timeZone: 'UTC' });\n  const S = (n, l, col) => `<div class=\"stat\"><div class=\"n\" style=\"color:${col}\">${n}</div><div class=\"l\">${l}</div></div>`;\n  const chart = (title, arr, col) => `<div class=\"card\"><div class=\"row\"><b class=\"grow\">${title}</b><b style=\"color:${col}\">${sum(arr)}</b></div>${spark(arr, col)}<div class=\"row muted\" style=\"font-size:11px;direction:ltr\"><span>${dd(first)}</span><span class=\"grow\"></span><span>${dd(last)}</span></div></div>`;\n  m.innerHTML = `<h1>التحليلات</h1><p class=\"sub\">آخر 30 يوم بتوقيت مكة. «نشط» = فتح التطبيق وهو مسجّل دخول.</p>\n    <div class=\"stats\">${S(c.users, 'مستخدم مسجّل', 'var(--purple)')}${S(c.d1, 'نشط اليوم', 'var(--green)')}${S(c.d7, 'نشط هالأسبوع', 'var(--green)')}${S(c.d30, 'نشط هالشهر', 'var(--green)')}\n    ${S(c.devices, 'جهاز للإشعارات', 'var(--skyDeep)')}${S(c.trips, 'سوّى رحلة', 'var(--orangeDeep)')}${S(c.visits, 'زيارة مؤكدة', 'var(--lilac)')}${S(c.reviews, 'تقييم', 'var(--orangeDeep)')}${S(c.merchants + ' / ' + c.coupons, 'تاجر / كوبون فعّال', 'var(--pinkDeep)')}${S(c.redeems, 'كوبون استُخدم', 'var(--pinkDeep)')}</div>\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:12px\">${chart('تسجيلات جديدة', s.signups, '#604C87')}${chart('أسئلة ونصائح', s.posts, '#2E86B8')}${chart('إجابات', s.answers, '#8E65AB')}${chart('تقييمات', s.reviews, '#E07B22')}${chart('زيارات مؤكدة', s.visits, '#3E8E5A')}${chart('كوبونات مستخدمة', s.redeems, '#C9506F')}</div>\n    <div style=\"display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;margin-top:14px\" class=\"msgGrid\">\n    <div class=\"card\"><b>المستخدمين حسب المدينة</b><div class=\"list\" style=\"margin-top:8px\">${d.cities.map((x) => `<div class=\"row\" style=\"font-size:14px\"><span class=\"grow\">${cityName(x.city)}</span><b>${x.n}</b></div>`).join('') || '<div class=\"muted\">ما اختاروا مدن للحين</div>'}</div></div>\n    <div class=\"card\"><b>أكثر الأماكن في «رحلتي»</b><div class=\"list\" style=\"margin-top:8px\">${d.places.map((x) => `<div class=\"row\" style=\"font-size:14px\"><span class=\"grow\">${h(x.title)} <span class=\"muted\" style=\"font-size:12px\">${cityName(x.city)}</span></span><b>${x.trips}</b><span class=\"muted\" style=\"font-size:12px\">${x.visits} زيارة</span></div>`).join('') || '<div class=\"muted\">ما فيه رحلات محفوظة للحين</div>'}</div></div></div>`;\n}\n\n/* ——— اقتراحات الزوار ——— */\nlet STAB = 'pending';\nconst SK = { new: ['مكان ناقص', 'b-live'], edit: ['تعديل', 'b-panel'], closed: ['مكان مقفل', 'b-hidden'] };\nasync function suggestView() {\n  const m = $('#main');\n  m.innerHTML = `<h1>اقتراحات الزوار</h1><p class=\"sub\">الزوار يقترحون أماكن ناقصة أو تعديلات. المكان الجديد ينضاف <b>مسودة</b> (تكمّل صوره وتنشره)، والتعديل يتطبق على طول. صاحب الاقتراح ياخذ +15 للمكان و+5 للتعديل.</p>\n    <div class=\"tabs\">${[['pending', 'تنتظر'], ['approved', 'انقبلت'], ['rejected', 'انرفضت']].map(([k, t]) => `<button data-s=\"${k}\" class=\"${STAB === k ? 'on' : ''}\">${t}</button>`).join('')}</div><div id=\"res\" class=\"list\"><p class=\"muted\">لحظة...</p></div>`;\n  m.querySelectorAll('[data-s]').forEach((b) => (b.onclick = () => { STAB = b.dataset.s; suggestView(); }));\n  const d = await api('/admin/suggestions?status=' + STAB);\n  const F = { title: 'الاسم', phone: 'الجوال', website: 'الموقع', address: 'العنوان', hours: 'الساعات' };\n  $('#res').innerHTML = d.suggestions.map((x) => {\n    const dd = x.data, pl = x.place;\n    const diff = Object.entries(F).filter(([k]) => dd[k]).map(([k, l]) => `<div class=\"row\" style=\"font-size:14px\"><label style=\"min-width:70px\">${STAB === 'pending' && x.type === 'edit' && k !== 'hours' ? `<input type=\"checkbox\" data-ap=\"${x.id}\" value=\"${k}\" checked> ` : ''}<b>${l}</b></label><span class=\"muted\" style=\"text-decoration:line-through\">${h(pl?.[k] || '—')}</span> ← <span>${h(dd[k])}</span></div>`).join('')\n      + (dd.lat && dd.lng ? `<div class=\"row\" style=\"font-size:14px\"><label>${STAB === 'pending' && x.type === 'edit' ? `<input type=\"checkbox\" data-ap=\"${x.id}\" value=\"geo\" checked> ` : ''}<b>الموقع</b></label><a target=\"_blank\" href=\"https://www.google.com/maps?q=${dd.lat},${dd.lng}\">${dd.lat}, ${dd.lng}</a></div>` : '');\n    return `<div class=\"post\"><div class=\"row\"><span class=\"badge ${SK[x.type][1]}\">${SK[x.type][0]}</span><b class=\"grow\">${h(x.type === 'new' ? dd.title : pl?.title || '')}</b><span class=\"muted\" style=\"font-size:13px\">${cityName(x.type === 'new' ? dd.city : pl?.city)} · ${h(x.user.name)} · ${dAr(x.created)}</span></div>\n      ${diff}${dd.note ? `<div style=\"font-size:14px\">«${h(dd.note)}»</div>` : ''}${x.note ? `<div class=\"muted\" style=\"font-size:13px\">ملاحظتك: ${h(x.note)}</div>` : ''}\n      ${pl ? `<div><a href=\"#\" data-open=\"${pl.id}\">افتح المكان في اللوحة</a></div>` : ''}\n      ${STAB === 'pending' ? `<div class=\"row\"><button class=\"btn g\" data-ok=\"${x.id}\">${x.type === 'new' ? 'اقبل وأضفه مسودة' : x.type === 'closed' ? 'اقبل وأخفِ المكان' : 'اقبل وطبّق المحدد'}</button><button class=\"btn p\" data-no=\"${x.id}\">رفض</button></div>` : ''}</div>`;\n  }).join('') || `<div class=\"empty\">${STAB === 'pending' ? 'ما فيه اقتراحات تنتظر' : 'ما فيه شي هنا'}</div>`;\n  m.querySelectorAll('[data-open]').forEach((a) => (a.onclick = async (e) => { e.preventDefault(); const r = await api('/admin/places/' + a.dataset.open); editPlace(r.place); }));\n  m.querySelectorAll('[data-ok]').forEach((b) => (b.onclick = async () => {\n    const id = b.dataset.ok;\n    const apply = [...m.querySelectorAll(`[data-ap=\"${id}\"]:checked`)].map((c) => c.value);\n    try {\n      const r = await api('/admin/suggestions/' + id, { method: 'POST', body: { status: 'approved', apply } });\n      toast('انقبل ووصله إشعار'); SUMMARY = null;\n      if (r.placeId && b.textContent.includes('مسودة') && confirm('انضاف كمسودة. تفتحه الحين وتكمّل صوره؟')) { const pr = await api('/admin/places/' + r.placeId); editPlace(pr.place); }\n      suggestView();\n    } catch (e) { toast(errMsg(e)); }\n  }));\n  m.querySelectorAll('[data-no]').forEach((b) => (b.onclick = async () => { const note = prompt('سبب الرفض (يوصله)؟'); if (note === null) return; await api('/admin/suggestions/' + b.dataset.no, { method: 'POST', body: { status: 'rejected', note } }); toast('انرفض'); SUMMARY = null; suggestView(); }));\n}\n\n/* ——— المميزات: إظهار وإخفاء ——— */\nasync function featuresView() {\n  const m = $('#main');\n  const d = await api('/admin/features');\n  m.innerHTML = `<h1>المميزات</h1><p class=\"sub\">أي ميزة تطفيها هنا تختفي من التطبيق خلال دقيقة، بدون تحديث. البيانات تبقى محفوظة، وترجع لما تشغلها.</p>\n    <div class=\"card\" style=\"max-width:640px\">${Object.entries(d.labels).map(([k, l]) => `<label class=\"row\" style=\"padding:12px 4px;border-bottom:1px solid var(--chip);cursor:pointer\"><span class=\"grow\" style=\"font-weight:600\">${h(l)}</span><span class=\"badge ${d.features[k] ? 'b-live' : 'b-hidden'}\" id=\"fb-${k}\">${d.features[k] ? 'ظاهرة' : 'مخفية'}</span><input type=\"checkbox\" data-f=\"${k}\" ${d.features[k] ? 'checked' : ''} style=\"width:22px;height:22px\"></label>`).join('')}</div>`;\n  m.querySelectorAll('[data-f]').forEach((c) => (c.onchange = async () => {\n    const r = await api('/admin/features', { method: 'POST', body: { [c.dataset.f]: c.checked } });\n    const on = r.features[c.dataset.f]; const b = $('#fb-' + c.dataset.f); b.textContent = on ? 'ظاهرة' : 'مخفية'; b.className = 'badge ' + (on ? 'b-live' : 'b-hidden');\n    toast(on ? 'رجعت للتطبيق' : 'انخفت من التطبيق');\n  }));\n}\n\n/* ——— أبطال الشهر (داخل صفحة الأوسمة) ——— */\nasync function heroesBlock(el) {\n  const city = el.dataset.city || '';\n  const d = await api('/admin/heroes' + (city ? '?city=' + city : ''));\n  el.innerHTML = `<div class=\"row\"><b class=\"grow\">أبطال ${h(d.month)}</b><select class=\"in\" style=\"width:auto\" id=\"hc\"><option value=\"\">كل المدن</option>${META.cities.map((c) => `<option value=\"${c.id}\" ${c.id === city ? 'selected' : ''}>${h(c.name)}</option>`).join('')}</select></div>\n    <p class=\"muted\" style=\"font-size:13px;margin:6px 0\">الترتيب من مساهمات الشهر: إجابة 5، أفضل إجابة 15، سؤال 2، تقييم 3، زيارة 10، صورة 5، سؤال سريع 1. يطلعون في المجتمع تلقائياً.</p>\n    <div class=\"list\">${d.heroes.map((x, i) => `<label class=\"row\" style=\"padding:6px 0;border-bottom:1px solid var(--chip)\"><input type=\"checkbox\" data-hero=\"${h(x.id)}\" ${i < 3 ? 'checked' : ''}><b style=\"width:22px\">${i + 1}</b><span class=\"grow\"><b>${h(x.name)}</b> ${x.guide ? '<span class=\"badge b-live\">مرشد</span>' : ''}<span class=\"muted\" style=\"font-size:12px\"> · ${x.answers} إجابة · ${x.reviews} تقييم · ${x.visits} زيارة</span></span><b style=\"color:var(--orangeDeep)\">${x.score}</b></label>`).join('') || '<div class=\"muted\">ما فيه مساهمات هالشهر للحين</div>'}</div>\n    ${d.heroes.length ? `<div class=\"row\" style=\"margin-top:10px\"><input class=\"in\" id=\"hb\" type=\"number\" value=\"50\" min=\"0\" max=\"500\" style=\"width:110px\"><span class=\"muted\">نقطة هدية</span><button class=\"btn o\" id=\"honor\">كرّم المحددين</button></div>` : ''}`;\n  $('#hc', el).onchange = (e) => { el.dataset.city = e.target.value; heroesBlock(el); };\n  $('#honor', el) && ($('#honor', el).onclick = async () => {\n    const ids = [...el.querySelectorAll('[data-hero]:checked')].map((c) => c.dataset.hero);\n    if (!ids.length) return toast('حدد أحد');\n    if (!confirm(`ترسل تكريم لـ ${ids.length} وتضيف لهم ${$('#hb', el).value} نقطة؟`)) return;\n    await api('/admin/heroes/honor', { method: 'POST', body: { userIds: ids, bonus: +$('#hb', el).value } }); toast('وصلهم التكريم');\n  });\n}\n\nrender();\n</script>\n</body>\n</html>\n";
